// RFID lab R7 Card manager.  uv run pio run -d labs/rfid-lab-r7 -e rfid-lab-r7 -t upload
// A bench door you manage from a React app (esp-labs/apps/door-app): add cards, name them, block
// them, give them an end date, hours or a number of uses, replace a lost one, write a label onto
// them, wipe their data blocks, save a card's data and write it back or copy it onto another
// card, watch the access log live. Two simulated locks (the screen and the LED): the front door,
// open to every role, and the admin room, admin cards only. The one reader is mounted at one of
// them at a time; the app or `at front|admin` moves it.
//
// The board keeps the card list (NVS) and decides every tap itself; the card only brings its
// UID. The app talks to the board's JSON API and WebSocket over your Wi-Fi (the network saved
// by W1/W2). Every change needs the admin token (serial: token), which the app's dev server adds.
//
// Wiring: the screen from lesson 03 and the RC522 as in R1. Push button on GPIO 5 optional.
// Views: door · cards · log   (button: click = next view)
// On-board LED (the lock the reader is at): green = open · red = denied · blue blinking = waiting for a new card ·
//               violet blinking = copy waiting for its second card · dim amber = lockdown ·
//               off = locked and quiet
// Serial: help · status · token · token new · cards · enroll <name> · open [front|admin] ·
//         at front|admin · lockdown on|off ·
//         saved · save [name] · restore <id> · copy · cancel · reset · tz <TZ>
#include <Arduino.h>
#include <ArduinoJson.h>
#include <WiFi.h>
#include <esp_system.h>

#include "api_token.h"
#include "button.h"
#include "color.h"
#include "connection.h"
#include "display.h"
#include "door.h"
#include "door_api.h"
#include "door_views.h"
#include "pins.h"
#include "registry.h"
#include "snapshots.h"

namespace {

const char *const kViewNames[] = {"door", "cards", "log"};
constexpr int kViews = 3;

Display display;
Connection connection;
ApiToken token;
Registry registry;
snap::Store snapshots;
Door doorTask(registry, snapshots);
DoorApi api(registry, snapshots, doorTask, token);
Button external(PIN_BUTTON, "button");
Button boot(PIN_BOOT_BTN, "BOOT");

struct {
  int view = 0;
  DoorState door;
  std::vector<door::Card> cards;  // copies for the screen, refreshed when the list changes
  std::vector<DoorEvent> events;
  uint32_t cardsVersion = 0, lastStatus = 0, lastEvents = 0;
  bool apiStarted = false;
} state;

// Why the board last started: a crash or a brownout shows up here (and in the app).
const char *resetReason() {
  switch (esp_reset_reason()) {
    case ESP_RST_POWERON: return "power on";
    case ESP_RST_SW: return "restart";
    case ESP_RST_PANIC: return "crash (panic)";
    case ESP_RST_INT_WDT:
    case ESP_RST_TASK_WDT:
    case ESP_RST_WDT: return "watchdog";
    case ESP_RST_BROWNOUT: return "brownout (supply dipped)";
    case ESP_RST_DEEPSLEEP: return "deep sleep";
    case ESP_RST_EXT: return "reset button";
    case ESP_RST_USB: return "USB";
    default: return "other";
  }
}

void printHelp() {
  Serial.println("\nRFID lab R7 Card manager  (rfid-lab-r7)");
  Serial.println("  status            Wi-Fi, address, reader chip, locks, card count");
  Serial.println("  token             the admin token for esp-labs/apps/door-app/.env (token new: replace it)");
  Serial.println("  cards             the card list");
  Serial.println("  enroll <name>     add a card as a resident: tap it within 20 s");
  Serial.println("  open [front|admin] open a lock for 5 s (the front door when left out)");
  Serial.println("  at front|admin    mount the reader at the front door or the admin room");
  Serial.println("  lockdown on|off   only maintenance and admin cards open while on");
  Serial.println("  saved             saved card data (blocks 4-6, 8-10)");
  Serial.println("  save [name]       save the data of the card on the reader");
  Serial.println("  restore <id>      write saved data onto the card on the reader");
  Serial.println("  copy              copy the card on the reader onto the next card you lay down");
  Serial.println("  cancel            stop waiting for a card (enroll, replace, copy)");
  Serial.println("  reset             hard reset of the reader chip");
  Serial.println("  tz <TZ>           time zone for the hours rules (POSIX string)");
  Serial.println("Button or BOOT: click = next view (door, cards, log)");
}

void printStatus() {
  const bool joined = connection.state() == Connection::State::Connected;
  Serial.printf("Wi-Fi: %s %s | http://%s.local (%s) | app clients %u\n", joined ? "joined" : "not joined",
                connection.ssid().c_str(), Connection::kHostname, joined ? WiFi.localIP().toString().c_str() : "-",
                unsigned(api.clients()));
  const auto lockLine = [](door::Lock l) {
    const DoorState::LockState &ls = state.door.locks[int(l)];
    Serial.printf("%s: %s%s | ", door::lockTitle(l),
                  ls.mode == DoorState::Mode::Open ? "open" : ls.mode == DoorState::Mode::Denied ? "denied" : "locked",
                  registry.readerAt() == l ? " (reader here)" : "");
  };
  lockLine(door::Lock::Front);
  lockLine(door::Lock::AdminRoom);
  Serial.println();
  Serial.printf("Reader chip 0x%02X (%s) | %d cards | lockdown %s | clock %s\n", state.door.chipVersion,
                rc522::versionName(state.door.chipVersion), registry.count(), registry.lockdown() ? "ON" : "off",
                connection.timeSynced() ? "synced" : "not yet (cards with dates or hours are refused until it is)");
  Serial.printf("Reader: %s | settings restored %u x | chip lost %u x | last problem: %s\n",
                state.door.irqMode ? "IRQ wire" : "polling", state.door.restores, state.door.lost,
                state.door.problem[0] ? state.door.problem : "none");
  Serial.printf("Board: up %lu s | last start: %s | free heap %u B\n", millis() / 1000, resetReason(), unsigned(ESP.getFreeHeap()));
}

void printCards() {
  door::Clock clk;
  doorjson::clockNow(clk);
  const auto list = registry.list();
  Serial.printf("%u card%s\n", unsigned(list.size()), list.size() == 1 ? "" : "s");
  for (const door::Card &c : list) {
    char uid[21];
    door::uidToHex(c.uid, c.uidLen, uid, sizeof(uid));
    Serial.printf("  %-14s %-20s %-11s front: %-13s admin room: %-13s taps %lu\n", uid, c.name, door::roleName(c.role),
                  door::decisionName(door::decide(&c, clk, registry.lockdown(), door::Lock::Front)),
                  door::decisionName(door::decide(&c, clk, registry.lockdown(), door::Lock::AdminRoom)),
                  static_cast<unsigned long>(c.taps));
  }
}

void printSaved() {
  const auto list = snapshots.list();
  Serial.printf("%u of %d places used\n", unsigned(list.size()), snap::Store::kMax);
  for (const snap::Snapshot &s : list) {
    char uid[21];
    door::uidToHex(s.uid, s.uidLen, uid, sizeof(uid));
    Serial.printf("  id %-3lu %-20s from %-14s %d of 6 blocks\n", static_cast<unsigned long>(s.id), s.name,
                  s.uidLen ? uid : "a file", s.count());
  }
}

void submit(Door::Job job, const char *name = "", uint32_t snapshot = 0, door::Lock lock = door::Lock::Front) {
  Door::Request r;
  r.job = job;
  r.lock = lock;
  strlcpy(r.name, name, sizeof(r.name));
  r.snapshot = snapshot;
  if (!doorTask.submit(r)) log_w("the reader is busy, try again");
}

void handleCommand(const String &raw) {
  String line = raw;
  line.trim();
  String lower = line;
  lower.toLowerCase();
  if (lower.isEmpty()) return;
  if (lower == "help" || lower == "?") return printHelp();
  if (lower == "status") return printStatus();
  if (lower == "cards") return printCards();
  if (lower == "open") return submit(Door::Job::Open);
  if (lower.startsWith("open ") || lower.startsWith("at ")) {
    door::Lock l;
    if (!door::lockFromId(lower.substring(lower.indexOf(' ') + 1).c_str(), l)) {
      log_w("which lock? front or admin");
      return;
    }
    if (lower.startsWith("open ")) return submit(Door::Job::Open, "", 0, l);
    registry.setReaderAt(l);
    log_i("the reader is now at the %s", door::lockTitle(l));
    return;
  }
  if (lower == "reset") return submit(Door::Job::ChipReset);
  if (lower == "saved") return printSaved();
  if (lower == "copy") return submit(Door::Job::Copy);
  if (lower == "cancel") return submit(Door::Job::Cancel);
  if (lower == "save" || lower.startsWith("save ")) {
    const String name = line.length() > 5 ? line.substring(5) : String();
    if (name.length() > 23) {
      log_w("save [name], up to 23 characters");
      return;
    }
    return submit(Door::Job::Save, name.c_str());
  }
  if (lower.startsWith("restore ")) {
    const long id = line.substring(8).toInt();
    if (id <= 0) {
      log_w("restore <id>  (saved lists the ids)");
      return;
    }
    return submit(Door::Job::Restore, "", uint32_t(id));
  }
  if (lower == "token") {
    Serial.printf("Admin token: %s\nPut it in esp-labs/apps/door-app/.env as BENCH_TOKEN=... (keep it out of chats and git)\n", token.value().c_str());
    return;
  }
  if (lower == "token new") {
    token.regenerate();
    Serial.printf("New admin token: %s (the old one stops working now; W2 shares it too)\n", token.value().c_str());
    return;
  }
  if (lower == "lockdown on" || lower == "lockdown off") {
    registry.setLockdown(lower == "lockdown on");
    log_i("lockdown %s", registry.lockdown() ? "ON: only maintenance and admin cards open" : "off");
    return;
  }
  if (lower.startsWith("enroll ")) {
    const String name = line.substring(7);
    if (name.isEmpty() || name.length() > 23) {
      log_w("enroll <name>, 1-23 characters");
      return;
    }
    return submit(Door::Job::Enroll, name.c_str());
  }
  if (lower.startsWith("tz ")) return connection.setTimezone(line.substring(3));
  log_w("unknown command '%s' (type help)", line.c_str());
}

void pollSerial() {
  static String buffer;
  while (Serial.available()) {
    const char c = Serial.read();
    if (c == '\n' || c == '\r') {
      if (!buffer.isEmpty()) handleCommand(buffer);
      buffer = "";
    } else if (c == 0x08 || c == 0x7F) {
      if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
    } else if (uint8_t(c) >= 0x20 && buffer.length() < 96) {
      buffer += c;
    }
  }
}

void handleButton(Button &b) {
  if (b.poll() == Button::Event::Click) {
    state.view = (state.view + 1) % kViews;
    log_i("view %d: %s", state.view + 1, kViewNames[state.view]);
  }
}

// The status every app client sees, once a second and whenever the door changes.
void publishStatus() {
  JsonDocument d;
  const bool joined = connection.state() == Connection::State::Connected;
  JsonObject chip = d["chip"].to<JsonObject>();
  char v[3];
  snprintf(v, sizeof(v), "%02X", state.door.chipVersion);
  chip["version"] = v;
  chip["name"] = rc522::versionName(state.door.chipVersion);
  chip["ok"] = state.door.chipVersion != 0x00 && state.door.chipVersion != 0xFF;
  JsonObject wifi = d["wifi"].to<JsonObject>();
  wifi["ssid"] = connection.ssid();
  wifi["ip"] = joined ? WiFi.localIP().toString() : String();
  wifi["rssi"] = joined ? WiFi.RSSI() : 0;
  door::Clock clk;
  doorjson::clockNow(clk);
  JsonObject clock = d["clock"].to<JsonObject>();
  clock["synced"] = clk.synced;
  clock["now"] = clk.now;
  const DoorState &s = state.door;
  JsonArray locks = d["locks"].to<JsonArray>();
  for (door::Lock l : {door::Lock::Front, door::Lock::AdminRoom}) {
    const DoorState::LockState &ls = s.locks[int(l)];
    JsonObject lj = locks.add<JsonObject>();
    lj["id"] = door::lockId(l);
    lj["title"] = door::lockTitle(l);
    lj["mode"] = ls.mode == DoorState::Mode::Open ? "open" : ls.mode == DoorState::Mode::Denied ? "denied" : "locked";
    lj["msLeft"] = ls.mode == DoorState::Mode::Locked ? 0 : max<int32_t>(0, int32_t(ls.modeUntil - millis()));
    lj["name"] = doorjson::copied(ls.lastName);
    lj["uid"] = doorjson::copied(ls.lastUid);
    lj["why"] = doorjson::copied(ls.lastWhy);
  }
  d["readerAt"] = door::lockId(registry.readerAt());
  if (s.present) d["present"] = doorjson::copied(s.presentUid);
  else d["present"] = nullptr;
  if (s.wait != DoorState::Wait::None) {
    JsonObject w = d["waiting"].to<JsonObject>();
    w["for"] = s.wait == DoorState::Wait::Enroll ? "enroll" : s.wait == DoorState::Wait::Replace ? "replace" : "copy";
    w["name"] = doorjson::copied(s.waitName);
    w["uid"] = doorjson::copied(s.waitUid);
    w["msLeft"] = max<int32_t>(0, int32_t(s.waitUntil - millis()));
  } else {
    d["waiting"] = nullptr;
  }
  d["lockdown"] = registry.lockdown();
  d["cards"] = registry.count();
  d["busy"] = s.busy != nullptr;
  JsonObject reader = d["reader"].to<JsonObject>();
  reader["wait"] = s.irqMode ? "irq" : "poll";
  reader["restores"] = s.restores;
  reader["lost"] = s.lost;
  reader["problem"] = doorjson::copied(s.problem);
  reader["problemAgo"] = s.problem[0] ? (millis() - s.problemAt) / 1000 : 0;
  JsonObject board = d["board"].to<JsonObject>();
  board["uptime"] = millis() / 1000;
  board["reset"] = resetReason();
  board["heap"] = ESP.getFreeHeap();
  String out;
  serializeJson(d, out);
  api.publishStatus(out);
}

// The on-board LED, written only when its colour changes.
void showLed() {
  static uint32_t shown = 0xFFFFFFFF;
  const DoorState &s = state.door;
  const DoorState::LockState &here = s.locks[int(registry.readerAt())];
  uint8_t r = 0, g = 0, b = 0;
  const bool blink = (millis() / 300) % 2;
  if (s.wait == DoorState::Wait::CopyTarget) r = blink ? 70 : 12, b = blink ? 120 : 20;
  else if (s.wait != DoorState::Wait::None) b = blink ? 120 : 20;
  else if (here.mode == DoorState::Mode::Open) g = 160, b = 40;
  else if (here.mode == DoorState::Mode::Denied) r = 150;
  else if (state.door.version && (s.chipVersion == 0x00 || s.chipVersion == 0xFF)) r = 90;
  else if (registry.lockdown()) r = 40, g = 18;
  const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
  if (colour == shown) return;
  shown = colour;
  rgbLedWrite(PIN_RGB, r, g, b);
}

}  // namespace

void setup() {
  Serial.begin(115200);
  delay(1500);
  if (!display.begin()) {
    log_e("No memory for the frame buffer. Stopping.");
    return;
  }
  rgbLedWrite(PIN_RGB, 0, 0, 0);
  external.begin();
  boot.begin();
  token.begin();
  registry.begin();
  snapshots.begin();
  connection.begin();
  doorTask.begin();
  log_i("rfid-lab-r7: reader task on core 0. Last start: %s. Type token for the app's .env, help for commands.", resetReason());
  printHelp();
}

void loop() {
  FrameBuffer &fb = display.fb();
  if (fb.pixels() == nullptr) {
    delay(1000);
    return;
  }
  const uint32_t now = millis();
  pollSerial();
  handleButton(external);
  handleButton(boot);
  connection.loop();
  // The web server starts once we have an address (the API is useless without one).
  if (!state.apiStarted && connection.state() == Connection::State::Connected) {
    api.begin();
    state.apiStarted = true;
    log_i("App: http://%s.local or http://%s  (set BENCH_URL in door-app/.env)", Connection::kHostname, WiFi.localIP().toString().c_str());
  }
  const bool changed = doorTask.update(state.door);
  if (state.apiStarted) {
    api.loop();
    if (changed || now - state.lastStatus >= 1000) {
      state.lastStatus = now;
      publishStatus();
    }
  }
  if (registry.version() != state.cardsVersion) {
    state.cardsVersion = registry.version();
    state.cards = registry.list();
  }
  if (now - state.lastEvents >= 500) {
    state.lastEvents = now;
    state.events = doorTask.events(0);
  }
  showLed();

  const float t = now / 1000.0f;
  fb.fillScreen(pal::night);
  door::Clock clk;
  doorjson::clockNow(clk);
  switch (state.view) {
    case 0: dv::door(fb, state.door, registry.readerAt(), int(state.cards.size()), t); break;
    case 1: dv::cards(fb, state.cards, clk, registry.lockdown(), registry.readerAt()); break;
    default: dv::history(fb, state.events); break;
  }
  dv::header(fb, kViewNames[state.view], state.view, kViews, state.door, registry.lockdown());
  char left[48], right[48];
  const bool joined = connection.state() == Connection::State::Connected;
  if (joined) snprintf(left, sizeof(left), "http://%s.local", Connection::kHostname);
  else snprintf(left, sizeof(left), "%s", connection.ssid().isEmpty() ? "no Wi-Fi saved: run W1 once" : "joining Wi-Fi...");
  snprintf(right, sizeof(right), "%s%u app", clk.synced ? "" : "no clock  ", unsigned(api.clients()));
  dv::footer(fb, left, right, joined ? pal::teal : pal::amber);
  display.push();
}

// R7's reader task: the only code that touches the RC522 (core 0). It
//   - polls for cards and checks each tap against the card list (registry.h + access_rules.h)
//   - drives two simulated locks (front door, admin room): the one the reader is mounted at
//     goes OPEN for 5 s when granted, DENIED for 2 s otherwise
//   - runs the app's card jobs, one at a time: enroll, replace, label, wipe, inspect, save,
//     restore, copy, open, chip reset
//   - waits for a card to be laid down when a job needs one (enroll, replace, copy's target)
// Results and events become JSON messages in an outbox; loop() sends them over the WebSocket.
//
// Guard rails, as in R4/R5: only the factory key, only the data blocks of sectors 1 and 2
// (4, 5, 6, 8, 9, 10), never block 0 or a sector trailer, and only where the access bits let
// key A write. "Wipe" means: those data blocks back to zeros. "Copy" and "restore" write saved
// data into the same blocks. Keys, trailers and the UID are never touched.
#pragma once

#include <ArduinoJson.h>
#include <freertos/queue.h>
#include <time.h>

#include <atomic>
#include <mutex>
#include <vector>

#include "access_rules.h"
#include "iso14443a.h"
#include "mfrc522.h"
#include "mifare_classic.h"
#include "pins.h"
#include "registry.h"
#include "snapshots.h"

namespace doorjson {

// ArduinoJson 7 takes a `const char[N]` for a string literal: it keeps only the pointer and
// sends all N-1 bytes. For a name field in a struct that is about to go away, that means the
// JSON later shows whatever reused the memory (the bug where a card's name became the tail of
// another card's JSON). Passing the field through here makes it a `const char *`, which is copied.
inline const char *copied(const char *s) { return s; }

inline void clockNow(door::Clock &c) {
  const time_t now = time(nullptr);
  c.synced = now > 1'700'000'000;
  c.now = uint32_t(now);
  struct tm lt;
  localtime_r(&now, &lt);
  c.hour = uint8_t(lt.tm_hour);
}

// One card as the app sees it, including what a tap would do right now at each lock.
inline void card(JsonObject o, const door::Card &c, const door::Clock &clk, bool lockdown) {
  char uid[21];
  door::uidToHex(c.uid, c.uidLen, uid, sizeof(uid));
  o["uid"] = uid;
  o["name"] = copied(c.name);
  o["role"] = door::roleName(c.role);
  o["blocked"] = c.blocked;
  o["validUntil"] = c.validUntil;
  o["fromHour"] = c.fromHour;
  o["toHour"] = c.toHour;
  o["usesLeft"] = c.usesLeft;
  o["added"] = c.added;
  o["lastSeen"] = c.lastSeen;
  o["taps"] = c.taps;
  JsonObject now = o["now"].to<JsonObject>();  // per lock: {"front": "granted", "admin": "admins only"}
  for (door::Lock l : {door::Lock::Front, door::Lock::AdminRoom})
    now[door::lockId(l)] = door::decisionName(door::decide(&c, clk, lockdown, l));
}

// Saved card data: only the blocks that were readable.
inline void snapshot(JsonObject o, const snap::Snapshot &s) {
  char uid[21];
  door::uidToHex(s.uid, s.uidLen, uid, sizeof(uid));
  o["id"] = s.id;
  o["name"] = copied(s.name);
  o["uid"] = uid;  // "" when imported from a file
  o["at"] = s.at;
  JsonArray blocks = o["blocks"].to<JsonArray>();
  for (int i = 0; i < snap::kBlocks; i++) {
    if (!(s.have & (1 << i))) continue;
    char hex[33];
    for (int k = 0; k < 16; k++) snprintf(hex + k * 2, 3, "%02X", s.data[i][k]);
    JsonObject b = blocks.add<JsonObject>();
    b["block"] = snap::kBlock[i];
    b["hex"] = hex;
  }
}

}  // namespace doorjson

struct DoorEvent {
  uint32_t seq = 0;
  uint32_t at = 0;  // unix seconds (0 before the clock syncs)
  char uid[21] = "";
  char name[24] = "";
  char what[24] = "";      // "tap", "enrolled", "label written", "card data saved", "data copied here", ...
  char decision[16] = "";  // for taps: granted, blocked, ...
  char lock[8] = "";       // taps and remote opens: "front" or "admin"
};

struct DoorState {
  enum class Mode : uint8_t { Locked, Open, Denied };
  struct LockState {
    Mode mode = Mode::Locked;
    uint32_t modeUntil = 0;  // millis()
    char lastName[24] = "", lastUid[21] = "", lastWhy[16] = "";
  };
  // Waiting for a card to be laid down: a new one (enroll), a replacement, or copy's target.
  enum class Wait : uint8_t { None, Enroll, Replace, CopyTarget };
  uint32_t version = 0;
  uint8_t chipVersion = 0;
  LockState locks[door::kLocks];  // indexed by door::Lock
  bool present = false;
  char presentUid[21] = "";
  Wait wait = Wait::None;
  uint32_t waitUntil = 0;  // millis()
  char waitName[24] = "";  // enroll, replace: the card's name; copy: where the data comes from
  char waitUid[21] = "";   // replace: the card being replaced; copy: the source card
  const char *busy = nullptr;
  // How the reader is doing, for the app's reader line.
  bool irqMode = false;     // waiting on the IRQ wire (false: polling the chip)
  uint16_t restores = 0;    // the chip reset itself (3.3 V dip) and its settings were put back
  uint16_t lost = 0;        // the chip stopped answering on SPI
  char problem[72] = "";    // the last thing that went wrong, in words
  uint32_t problemAt = 0;   // millis()
};

class Door {
 public:
  enum class Job : uint8_t { Enroll, Replace, Cancel, Label, Wipe, Inspect, Save, Restore, Copy, Open, ChipReset };
  struct Request {
    Job job = Job::Open;
    uint32_t id = 0;
    uint8_t uid[10] = {};
    uint8_t uidLen = 0;
    char name[24] = "";
    door::Role role = door::Role::Resident;
    door::Lock lock = door::Lock::Front;  // open: which lock
    uint32_t snapshot = 0;                // restore: which saved data
  };

  static constexpr uint32_t kOpenMs = 5000, kDeniedMs = 2000, kWaitMs = 20000;

  Door(Registry &reg, snap::Store &snaps) : reg_(reg), snaps_(snaps) {}

  void begin() {
    mailbox_ = xQueueCreate(6, sizeof(Request));
    xTaskCreatePinnedToCore(task, "door", 12 * 1024, this, 2, nullptr, 0);
  }

  // From any task. Returns the job id (the app waits for a "job" message with it), 0 when busy.
  uint32_t submit(Request r) {
    r.id = nextId_++;
    return xQueueSend(mailbox_, &r, 0) == pdTRUE ? r.id : 0;
  }

  bool update(DoorState &mine) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (mine.version == state_.version) return false;
    mine = state_;
    return true;
  }

  std::vector<DoorEvent> events(uint32_t since) {
    std::lock_guard<std::mutex> lock(mutex_);
    std::vector<DoorEvent> out;
    for (const DoorEvent &e : events_)
      if (e.seq > since) out.push_back(e);
    return out;
  }

  // The next WebSocket message (JSON text), if any.
  bool takeMessage(String &out) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (outbox_.empty()) return false;
    out = std::move(outbox_.front());
    outbox_.erase(outbox_.begin());
    return true;
  }

 private:
  static void task(void *self) { static_cast<Door *>(self)->run(); }

  void run() {
    spi_ = new SPIClass(HSPI);
    const uint8_t v = chip_.begin(*spi_, {PIN_RFID_SS, PIN_RFID_SCK, PIN_RFID_MOSI, PIN_RFID_MISO, PIN_RFID_RST, PIN_RFID_IRQ}, nullptr);
    if (chip_.hasIrqPin()) chip_.setWaitMode(rc522::Mfrc522::WaitMode::Irq);
    log_i("RC522: VersionReg 0x%02X (%s)", v, rc522::versionName(v));
    chipLost_ = v == 0x00 || v == 0xFF;
    if (chipLost_) problem("reader chip not answering: check its 3.3V, GND and MISO wires");
    publish([&](DoorState &s) { s.chipVersion = v, s.irqMode = chip_.waitMode() == rc522::Mfrc522::WaitMode::Irq; });
    for (;;) {
      Request r;
      if (xQueueReceive(mailbox_, &r, pdMS_TO_TICKS(80)) == pdTRUE) {
        publish([&](DoorState &s) { s.busy = "working"; });
        perform(r);
        chip_.stopCrypto1();
        checkIrq();
        publish([&](DoorState &s) { s.busy = nullptr; });
        continue;
      }
      if (millis() - lastHealth_ >= 2000) health();
      if (!chipLost_) pollOnce();
      tickDoor();
    }
  }

  // ---- State, events, outbox ---------------------------------------------------------------

  template <typename F>
  void publish(F change) {
    std::lock_guard<std::mutex> lock(mutex_);
    change(state_);
    state_.version++;
  }

  void send(const char *type, JsonDocument &data) {
    JsonDocument msg;
    msg["type"] = type;
    msg["data"] = data;
    String text;
    serializeJson(msg, text);
    std::lock_guard<std::mutex> lock(mutex_);
    if (outbox_.size() >= 24) outbox_.erase(outbox_.begin());
    outbox_.push_back(std::move(text));
  }

  // The last thing that went wrong with the reader, for the app (and the serial log).
  void problem(const char *what) {
    log_w("reader: %s", what);
    publish([&](DoorState &s) {
      strlcpy(s.problem, what, sizeof(s.problem));
      s.problemAt = millis();
    });
  }

  // The IRQ wire stayed quiet although the chip finished: poll the chip instead (as R1-R6 do).
  // Without this, every frame waits out the whole timeout and reading a card crawls.
  void checkIrq() {
    if (!chip_.takeIrqMissed() || chip_.waitMode() != rc522::Mfrc522::WaitMode::Irq) return;
    chip_.setWaitMode(rc522::Mfrc522::WaitMode::Poll);
    publish([](DoorState &s) { s.irqMode = false; });
    char msg[72];
    snprintf(msg, sizeof(msg), "IRQ wire on GPIO %d stays quiet: polling instead", PIN_RFID_IRQ);
    problem(msg);
  }

  // Settings gone after a 3.3 V dip (VersionReg still fine, antenna off): put them back.
  bool restoreIfReset() {
    if (!chip_.settingsLost()) return false;
    chip_.restoreSettings();
    publish([](DoorState &s) { s.restores++; });
    problem("the reader chip reset itself (3.3V dip?): settings restored");
    return true;
  }

  void event(const char *uid, const char *name, const char *what, const char *decision = "", const char *lock = "") {
    DoorEvent e;
    door::Clock clk;
    doorjson::clockNow(clk);
    e.at = clk.synced ? clk.now : 0;
    strlcpy(e.uid, uid, sizeof(e.uid));
    strlcpy(e.name, name, sizeof(e.name));
    strlcpy(e.what, what, sizeof(e.what));
    strlcpy(e.decision, decision, sizeof(e.decision));
    strlcpy(e.lock, lock, sizeof(e.lock));
    {
      std::lock_guard<std::mutex> lock(mutex_);
      e.seq = ++eventSeq_;
      if (events_.size() >= 50) events_.erase(events_.begin());
      events_.push_back(e);
    }
    log_i("%s %s %s %s %s", what, lock, name[0] ? name : uid, decision, e.at ? "" : "(no clock yet)");
    JsonDocument d;
    d["seq"] = e.seq, d["at"] = e.at, d["uid"] = doorjson::copied(e.uid), d["name"] = doorjson::copied(e.name), d["what"] = doorjson::copied(e.what),
        d["decision"] = doorjson::copied(e.decision), d["lock"] = doorjson::copied(e.lock);
    send("event", d);
  }

  void finish(uint32_t id, bool ok, const char *message, JsonDocument *data = nullptr) {
    if (ok) log_i("job %lu: %s", static_cast<unsigned long>(id), message);
    else log_w("job %lu: %s", static_cast<unsigned long>(id), message);
    JsonDocument d;
    d["id"] = id, d["ok"] = ok, d["message"] = message;
    if (data) d["data"] = *data;
    send("job", d);
  }

  void setDoor(door::Lock at, DoorState::Mode mode, uint32_t ms, const char *name, const char *uid, const char *why) {
    publish([&](DoorState &s) {
      DoorState::LockState &l = s.locks[int(at)];
      l.mode = mode;
      l.modeUntil = millis() + ms;
      strlcpy(l.lastName, name, sizeof(l.lastName));
      strlcpy(l.lastUid, uid, sizeof(l.lastUid));
      strlcpy(l.lastWhy, why, sizeof(l.lastWhy));
    });
  }

  // Each lock back to locked after its time; waiting for a card gives up after 20 s.
  void tickDoor() {
    const uint32_t now = millis();
    bool relock = false;
    {
      std::lock_guard<std::mutex> lock(mutex_);
      for (const DoorState::LockState &l : state_.locks)
        relock |= l.mode != DoorState::Mode::Locked && int32_t(now - l.modeUntil) >= 0;
    }
    if (relock)
      publish([now](DoorState &s) {
        for (DoorState::LockState &l : s.locks)
          if (l.mode != DoorState::Mode::Locked && int32_t(now - l.modeUntil) >= 0) l.mode = DoorState::Mode::Locked;
      });
    if (wait_ != DoorState::Wait::None && int32_t(now - waitUntil_) >= 0) {
      const bool copy = wait_ == DoorState::Wait::CopyTarget;
      stopWait();
      finish(waitJob_, false, copy ? "no second card within 20 s: nothing was written" : "no new card within 20 s");
    }
  }

  void startWait(DoorState::Wait w, uint32_t job, const char *name, const char *uid) {
    wait_ = w, waitJob_ = job, waitUntil_ = millis() + kWaitMs;
    publish([&](DoorState &s) {
      s.wait = w;
      s.waitUntil = waitUntil_;
      strlcpy(s.waitName, name, sizeof(s.waitName));
      strlcpy(s.waitUid, uid, sizeof(s.waitUid));
    });
  }

  void stopWait() {
    wait_ = DoorState::Wait::None;
    publish([](DoorState &s) { s.wait = DoorState::Wait::None, s.waitName[0] = 0, s.waitUid[0] = 0; });
  }

  // ---- Polling and taps ----------------------------------------------------------------------

  void pollOnce() {
    iso14443a::Uid u;
    const bool found = iso14443a::wakeAndSelect(chip_, u) == rc522::Status::Ok;
    if (found) iso14443a::halt(chip_);
    chip_.stopCrypto1();
    checkIrq();
    const bool isNew = found && (!present_ || !u.sameAs(current_));
    if (found) misses_ = 0;
    if (isNew) {
      present_ = true, current_ = u;
      char hex[21];
      door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
      publish([&](DoorState &s) { s.present = true, strlcpy(s.presentUid, hex, sizeof(s.presentUid)); });
      onCard(u, hex);
    } else if (!found && present_ && ++misses_ >= 3) {
      present_ = false;
      publish([](DoorState &s) { s.present = false, s.presentUid[0] = 0; });
    }
  }

  void onCard(const iso14443a::Uid &u, const char *hex) {
    switch (wait_) {
      case DoorState::Wait::Enroll: return enroll(u, hex);
      case DoorState::Wait::Replace: return replace(u, hex);
      case DoorState::Wait::CopyTarget: return copyOnto(u, hex);
      case DoorState::Wait::None: break;
    }

    door::Clock clk;
    doorjson::clockNow(clk);
    door::Card c;
    bool known = false;
    const door::Lock at = reg_.readerAt();
    const door::Decision d = reg_.tap(u.bytes, u.size, clk, at, c, known);
    const char *why = door::decisionName(d);
    if (d == door::Decision::Granted) setDoor(at, DoorState::Mode::Open, kOpenMs, c.name, hex, why);
    else setDoor(at, DoorState::Mode::Denied, kDeniedMs, known ? c.name : "", hex, why);
    event(hex, known ? c.name : "", "tap", why, door::lockId(at));
  }

  void enroll(const iso14443a::Uid &u, const char *hex) {
    const uint32_t job = waitJob_;
    stopWait();
    door::Card existing;
    if (reg_.get(u.bytes, u.size, existing)) {
      char msg[80];
      snprintf(msg, sizeof(msg), "this card is already in the list as \"%s\"", existing.name);
      return finish(job, false, msg);
    }
    door::Card c;
    memcpy(c.uid, u.bytes, u.size);
    c.uidLen = u.size;
    strlcpy(c.name, enrollName_, sizeof(c.name));
    c.role = enrollRole_;
    c.usesLeft = c.role == door::Role::Guest ? 5 : -1;  // guests start with 5 uses; the app can change it
    door::Clock clk;
    doorjson::clockNow(clk);
    c.added = clk.synced ? clk.now : 0;
    const Registry::AddResult r = reg_.add(c);
    if (r == Registry::AddResult::Full) return finish(job, false, "the list is full (20 cards)");
    if (r == Registry::AddResult::Exists) return finish(job, false, "this card is already in the list");
    event(hex, c.name, "enrolled");
    JsonDocument d;
    doorjson::card(d.to<JsonObject>(), c, clk, reg_.lockdown());
    finish(job, true, "card added", &d);
  }

  // A lost or broken card: the new card takes over the old one's name, role and every rule; the
  // old one stays in the list, blocked and renamed "<name> old", so a tap with it shows in the log.
  void replace(const iso14443a::Uid &u, const char *hex) {
    if (u.size == replaceLen_ && memcmp(u.bytes, replaceUid_, u.size) == 0) {
      log_i("that's the card being replaced: lay the new one");
      return;  // keep waiting
    }
    const uint32_t job = waitJob_;
    stopWait();
    door::Card existing, old;
    if (reg_.get(u.bytes, u.size, existing)) {
      char msg[80];
      snprintf(msg, sizeof(msg), "this card is already in the list as \"%s\"", existing.name);
      return finish(job, false, msg);
    }
    if (!reg_.get(replaceUid_, replaceLen_, old)) return finish(job, false, "the old card is no longer in the list");
    door::Card c = old;
    memset(c.uid, 0, sizeof(c.uid));
    memcpy(c.uid, u.bytes, u.size);
    c.uidLen = u.size;
    c.blocked = false;
    c.taps = 0, c.lastSeen = 0;
    door::Clock clk;
    doorjson::clockNow(clk);
    c.added = clk.synced ? clk.now : 0;
    if (reg_.add(c) != Registry::AddResult::Added) return finish(job, false, "the list is full (20 cards): remove one first");
    char oldName[24], oldHex[21];
    snprintf(oldName, sizeof(oldName), "%.19s old", old.name);
    reg_.update(replaceUid_, replaceLen_, [&](door::Card &o) {
      o.blocked = true;
      strlcpy(o.name, oldName, sizeof(o.name));
    });
    door::uidToHex(old.uid, old.uidLen, oldHex, sizeof(oldHex));
    event(oldHex, oldName, "blocked: replaced");
    event(hex, c.name, "replacement added");
    JsonDocument d;
    doorjson::card(d.to<JsonObject>(), c, clk, reg_.lockdown());
    finish(job, true, "new card added with the same rules; the old one is blocked", &d);
  }

  // Copy, second half: the saved data from the first card goes onto this one.
  void copyOnto(const iso14443a::Uid &seen, const char *hex) {
    if (seen.size == copySrc_.uidLen && memcmp(seen.bytes, copySrc_.uid, seen.size) == 0) {
      log_i("that's the source card: lay the card to copy onto");
      return;  // keep waiting
    }
    const uint32_t job = waitJob_;
    stopWait();
    iso14443a::Uid u;  // polling halted it: wake it again
    if (selectCard(u) != rc522::Status::Ok || !u.sameAs(seen))
      return finish(job, false, "the card moved away: keep it still and copy again");
    JsonDocument d;
    const int n = writeSnapshot(u, copySrc_, d);
    iso14443a::halt(chip_);
    door::Card c;
    const bool listed = reg_.get(u.bytes, u.size, c);
    char msg[112];
    snprintf(msg, sizeof(msg), "%d of %d blocks copied from %s onto %s", n, copySrc_.count(), copySrc_.name, hex);
    event(hex, listed ? c.name : "", "data copied here");
    finish(job, n == copySrc_.count(), msg, &d);
  }

  // Refuse a second wait while one runs: one card at a time.
  bool waitFree(const Request &r) {
    if (wait_ == DoorState::Wait::None) return true;
    finish(r.id, false, "the board is already waiting for a card: cancel that first");
    return false;
  }

  // ---- Jobs from the app ----------------------------------------------------------------------

  void perform(const Request &r) {
    switch (r.job) {
      case Job::Enroll: {
        if (!waitFree(r)) return;
        enrollRole_ = r.role;
        strlcpy(enrollName_, r.name, sizeof(enrollName_));
        present_ = false;  // a card already lying there counts as a new tap for enrollment
        startWait(DoorState::Wait::Enroll, r.id, r.name, "");
        log_i("enroll \"%s\": tap the new card within 20 s", r.name);
        return;
      }
      case Job::Replace: {
        if (!waitFree(r)) return;
        door::Card old;
        if (!reg_.get(r.uid, r.uidLen, old)) return finish(r.id, false, "no card with this uid in the list");
        memcpy(replaceUid_, r.uid, r.uidLen);
        replaceLen_ = r.uidLen;
        char hex[21];
        door::uidToHex(r.uid, r.uidLen, hex, sizeof(hex));
        present_ = false;
        startWait(DoorState::Wait::Replace, r.id, old.name, hex);
        log_i("replace \"%s\": tap the new card within 20 s", old.name);
        return;
      }
      case Job::Cancel: {
        if (wait_ != DoorState::Wait::None) {
          const uint32_t job = waitJob_;
          stopWait();
          finish(job, false, "cancelled");
        }
        return finish(r.id, true, "cancelled");
      }
      case Job::Open: {
        setDoor(r.lock, DoorState::Mode::Open, kOpenMs, "the app", "", "remote open");
        event("", "the app", "opened from the app", "", door::lockId(r.lock));
        char msg[40];
        snprintf(msg, sizeof(msg), "%s open for 5 s", door::lockTitle(r.lock));
        return finish(r.id, true, msg);
      }
      case Job::ChipReset: {
        chip_.hardReset();
        const uint8_t v = chip_.read(rc522::VersionReg);
        chipLost_ = v == 0x00 || v == 0xFF;
        publish([&](DoorState &s) { s.chipVersion = v; });
        char msg[48];
        snprintf(msg, sizeof(msg), "chip reset: VersionReg 0x%02X", v);
        return finish(r.id, !chipLost_, msg);
      }
      case Job::Label: return label(r);
      case Job::Wipe: return wipe(r);
      case Job::Inspect: return inspect(r);
      case Job::Save: return save(r);
      case Job::Restore: return restore(r);
      case Job::Copy: return copyStart(r);
    }
  }

  // Wake and select the card on the reader for a job. Three tries, with the field switched off
  // for 5 ms in between (the card restarts): a card at the edge of the field often answers on
  // the second try. If nothing answers, check the chip didn't lose its settings and try once more.
  rc522::Status selectCard(iso14443a::Uid &u) {
    rc522::Status s = rc522::Status::NoAnswer;
    for (int i = 0; i < 3; i++) {
      s = iso14443a::wakeAndSelect(chip_, u);
      if (s == rc522::Status::Ok || s == rc522::Status::ChipSilent) break;
      chip_.antenna(false);
      delay(5);
      chip_.antenna(true);
      delay(5);
    }
    if (s != rc522::Status::Ok && restoreIfReset()) s = iso14443a::wakeAndSelect(chip_, u);
    checkIrq();
    return s;
  }

  // Why selectCard() failed, in words. `noCard` is the job's own "lay the card down" sentence.
  static const char *whyNot(rc522::Status s, const char *noCard) {
    if (s == rc522::Status::NoAnswer) return noCard;
    if (s == rc522::Status::ChipSilent) return "the reader chip isn't answering: check its 3.3V, GND and MISO wires";
    return "a card answered, but garbled: lay it flat and still, in the middle of the reader";
  }

  // The card with this UID must be on the reader. Returns false (and finishes the job) if not.
  bool cardOnReader(const Request &r, iso14443a::Uid &u, door::Card &listed) {
    const bool inList = reg_.get(r.uid, r.uidLen, listed);
    const rc522::Status s = selectCard(u);
    char msg[96];
    if (s != rc522::Status::Ok) {
      snprintf(msg, sizeof(msg), "put %s on the reader first", inList ? listed.name : "the card");
      finish(r.id, false, whyNot(s, msg));
      return false;
    }
    if (u.size != r.uidLen || memcmp(u.bytes, r.uid, r.uidLen) != 0) {
      finish(r.id, false, "a different card is on the reader");
      return false;
    }
    return true;
  }

  bool openSector(iso14443a::Uid &u, uint8_t firstBlock, rfid::AccessBits &ab) {
    if (mifare::authA(chip_, u, firstBlock, mifare::kFactoryKey) != rc522::Status::Ok) {
      mifare::reselect(chip_, u);
      return false;
    }
    uint8_t t[16];
    return mifare::readBlock(chip_, uint8_t(firstBlock + 3), t) == rc522::Status::Ok && rfid::AccessBits::decode(t, ab);
  }

  // Blocks 4 and 5: the name and the role, as a label anyone can read with the factory key.
  // The door never trusts it: access is decided by the board's list only.
  void label(const Request &r) {
    iso14443a::Uid u;
    door::Card c;
    if (!cardOnReader(r, u, c)) return;
    if (!c.uidLen) return finish(r.id, false, "add this card to the list first");
    rfid::AccessBits ab;
    if (!openSector(u, 4, ab)) return finish(r.id, false, "sector 1 doesn't open with the factory key");
    if (!ab.keyAWrites(0) || !ab.keyAWrites(1)) return finish(r.id, false, "sector 1's access bits don't allow writes");
    uint8_t b4[16] = {}, b5[16] = {}, back[16];
    strncpy(reinterpret_cast<char *>(b4), c.name, 16);
    snprintf(reinterpret_cast<char *>(b5), 16, "R7 %s", door::roleName(c.role));
    bool ok = mifare::writeBlock(chip_, 4, b4) == rc522::Status::Ok && mifare::readBlock(chip_, 4, back) == rc522::Status::Ok &&
              memcmp(back, b4, 16) == 0;
    ok = ok && mifare::writeBlock(chip_, 5, b5) == rc522::Status::Ok && mifare::readBlock(chip_, 5, back) == rc522::Status::Ok &&
         memcmp(back, b5, 16) == 0;
    iso14443a::halt(chip_);
    if (!ok) return finish(r.id, false, "writing failed: keep the card still and try again");
    char hex[21];
    door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
    event(hex, c.name, "label written");
    finish(r.id, true, "label written to blocks 4 and 5");
  }

  // Data blocks of sectors 1 and 2 back to zeros, where the access bits allow it.
  void wipe(const Request &r) {
    iso14443a::Uid u;
    door::Card c;
    if (!cardOnReader(r, u, c)) return;
    JsonDocument d;
    JsonArray cleared = d["cleared"].to<JsonArray>(), skipped = d["skipped"].to<JsonArray>();
    const uint8_t zeros[16] = {};
    for (uint8_t first : {uint8_t(4), uint8_t(8)}) {
      rfid::AccessBits ab;
      if (!openSector(u, first, ab)) {
        for (int b = 0; b < 3; b++) skipped.add(first + b);
        continue;
      }
      for (int b = 0; b < 3; b++) {
        const uint8_t block = uint8_t(first + b);
        uint8_t back[16];
        const bool ok = ab.keyAWrites(b) && mifare::writeBlock(chip_, block, zeros) == rc522::Status::Ok &&
                        mifare::readBlock(chip_, block, back) == rc522::Status::Ok && memcmp(back, zeros, 16) == 0;
        (ok ? cleared : skipped).add(block);
      }
    }
    iso14443a::halt(chip_);
    char hex[21], msg[64];
    door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
    snprintf(msg, sizeof(msg), "%u of 6 data blocks cleared", unsigned(cleared.size()));
    event(hex, c.uidLen ? c.name : "", "card wiped");
    finish(r.id, cleared.size() > 0, msg, &d);
  }

  // Whatever card is on the reader: its UID, type, whether it's in the list, blocks 4-6 and 8-10.
  void inspect(const Request &r) {
    iso14443a::Uid u;
    const rc522::Status st = selectCard(u);
    if (st != rc522::Status::Ok) return finish(r.id, false, whyNot(st, "no card on the reader"));
    char hex[21];
    door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
    door::Card c;
    JsonDocument d;
    d["uid"] = hex;
    d["type"] = rfid::cardType(u.sak);
    d["listed"] = reg_.get(u.bytes, u.size, c);
    if (c.uidLen) d["name"] = doorjson::copied(c.name);
    JsonArray blocks = d["blocks"].to<JsonArray>();
    for (uint8_t first : {uint8_t(4), uint8_t(8)}) {
      rfid::AccessBits ab;
      const bool open = openSector(u, first, ab);
      for (int b = 0; b < 3; b++) {
        JsonObject o = blocks.add<JsonObject>();
        o["block"] = first + b;
        uint8_t data[16];
        if (!open || mifare::readBlock(chip_, uint8_t(first + b), data) != rc522::Status::Ok) {
          o["closed"] = true;
          continue;
        }
        char h[33], text[17];
        for (int i = 0; i < 16; i++) {
          snprintf(h + i * 2, 3, "%02X", data[i]);
          text[i] = data[i] >= 32 && data[i] < 127 ? char(data[i]) : '.';
        }
        text[16] = 0;
        o["hex"] = h;
        o["text"] = text;
        int32_t value;
        uint8_t addr;
        if (rfid::ValueBlock::decode(data, value, addr)) o["value"] = value;
      }
    }
    iso14443a::halt(chip_);
    finish(r.id, true, "card read", &d);
  }

  // ---- Saved card data: save, restore, copy -----------------------------------------------------

  // The lab blocks that open with the factory key, into `s`. Returns how many were read.
  int readSnapshot(iso14443a::Uid &u, snap::Snapshot &s) {
    memcpy(s.uid, u.bytes, u.size);
    s.uidLen = u.size;
    door::Clock clk;
    doorjson::clockNow(clk);
    s.at = clk.synced ? clk.now : 0;
    s.have = 0;
    for (uint8_t first : {uint8_t(4), uint8_t(8)}) {
      rfid::AccessBits ab;
      if (!openSector(u, first, ab)) continue;
      for (int b = 0; b < 3; b++) {
        const int i = snap::slotOf(first + b);
        if (mifare::readBlock(chip_, uint8_t(first + b), s.data[i]) == rc522::Status::Ok) s.have |= uint8_t(1 << i);
      }
    }
    return s.count();
  }

  // The saved blocks onto the card `u`, each read back to check. Returns how many match now.
  int writeSnapshot(iso14443a::Uid &u, const snap::Snapshot &s, JsonDocument &d) {
    JsonArray written = d["written"].to<JsonArray>(), skipped = d["skipped"].to<JsonArray>();
    int n = 0;
    for (uint8_t first : {uint8_t(4), uint8_t(8)}) {
      const int base = snap::slotOf(first);
      if (!(s.have & (7 << base))) continue;  // nothing saved from this sector
      rfid::AccessBits ab;
      const bool open = openSector(u, first, ab);
      for (int b = 0; b < 3; b++) {
        const int i = base + b;
        if (!(s.have & (1 << i))) continue;
        const uint8_t block = uint8_t(first + b);
        uint8_t back[16];
        const bool ok = open && ab.keyAWrites(b) && mifare::writeBlock(chip_, block, s.data[i]) == rc522::Status::Ok &&
                        mifare::readBlock(chip_, block, back) == rc522::Status::Ok && memcmp(back, s.data[i], 16) == 0;
        (ok ? written : skipped).add(block);
        n += ok;
      }
    }
    return n;
  }

  // Whatever card is on the reader, listed or not: its lab blocks become a named snapshot.
  void save(const Request &r) {
    iso14443a::Uid u;
    const rc522::Status st = selectCard(u);
    if (st != rc522::Status::Ok) return finish(r.id, false, whyNot(st, "lay the card to save on the reader first"));
    snap::Snapshot s;
    const int n = readSnapshot(u, s);
    iso14443a::halt(chip_);
    if (!n) return finish(r.id, false, "no lab block opens with the factory key: nothing to save");
    char hex[21];
    door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
    door::Card c;
    const bool listed = reg_.get(u.bytes, u.size, c);
    strlcpy(s.name, r.name[0] ? r.name : listed ? c.name : hex, sizeof(s.name));
    if (!snaps_.add(s)) return finish(r.id, false, "8 snapshots saved already: delete one first");
    event(hex, listed ? c.name : "", "card data saved");
    JsonDocument d;
    doorjson::snapshot(d.to<JsonObject>(), s);
    char msg[80];
    snprintf(msg, sizeof(msg), "%d of 6 blocks saved as \"%s\"", n, s.name);
    finish(r.id, true, msg, &d);
  }

  // A snapshot onto the card on the reader: the card it came from (restore) or another (copy).
  void restore(const Request &r) {
    snap::Snapshot s;
    if (!snaps_.get(r.snapshot, s)) return finish(r.id, false, "no saved data with this id");
    iso14443a::Uid u;
    const rc522::Status st = selectCard(u);
    if (st != rc522::Status::Ok) return finish(r.id, false, whyNot(st, "lay the card to write on the reader first"));
    JsonDocument d;
    const int n = writeSnapshot(u, s, d);
    iso14443a::halt(chip_);
    char hex[21], msg[128];
    door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
    const bool same = s.uidLen == u.size && memcmp(s.uid, u.bytes, u.size) == 0;
    snprintf(msg, sizeof(msg), "%d of %d blocks of \"%s\" written to %s%s", n, s.count(), s.name, hex,
             same ? " (the card it came from)" : "");
    door::Card c;
    const bool listed = reg_.get(u.bytes, u.size, c);
    event(hex, listed ? c.name : "", same ? "data restored" : "data copied here");
    finish(r.id, n == s.count(), msg, &d);
  }

  // Copy, first half: read the source card now, then wait for a different card (copyOnto).
  void copyStart(const Request &r) {
    if (!waitFree(r)) return;
    iso14443a::Uid u;
    const rc522::Status st = selectCard(u);
    if (st != rc522::Status::Ok) return finish(r.id, false, whyNot(st, "lay the card to copy from on the reader first"));
    copySrc_ = snap::Snapshot{};
    const int n = readSnapshot(u, copySrc_);
    iso14443a::halt(chip_);
    if (!n) return finish(r.id, false, "no lab block opens with the factory key: nothing to copy");
    char hex[21];
    door::uidToHex(u.bytes, u.size, hex, sizeof(hex));
    door::Card c;
    strlcpy(copySrc_.name, reg_.get(u.bytes, u.size, c) ? c.name : hex, sizeof(copySrc_.name));
    present_ = true, current_ = u;  // the source still lying there is not the target
    startWait(DoorState::Wait::CopyTarget, r.id, copySrc_.name, hex);
    log_i("copy: %d blocks read from %s; lay the card to copy onto within 20 s", n, hex);
  }

  // ---- Is the chip still there? (as in the R1-R6 labs) -------------------------------------------

  // Every 2 s: does the chip still answer, and does it still have our settings?
  void health() {
    lastHealth_ = millis();
    const uint8_t v = chip_.read(rc522::VersionReg);
    const bool alive = v != 0x00 && v != 0xFF;
    if (alive && !chipLost_) {
      restoreIfReset();
      return;
    }
    if (alive == !chipLost_) return;
    if (!alive) {
      chip_.hardReset();
      const uint8_t again = chip_.read(rc522::VersionReg);
      chipLost_ = again == 0x00 || again == 0xFF;
      log_w("RC522 stopped answering (0x%02X); after a hard reset: 0x%02X%s", v, again, chipLost_ ? " - check 3.3V, GND, MISO" : "");
      publish([&](DoorState &s) { s.chipVersion = again, s.lost++; });
      problem(chipLost_ ? "reader chip stopped answering: check its 3.3V, GND and MISO wires"
                        : "reader chip had hung: a hard reset brought it back");
    } else {
      chipLost_ = false;
      log_i("RC522 answering again: 0x%02X", v);
      publish([&](DoorState &s) { s.chipVersion = v; });
    }
  }

  Registry &reg_;
  snap::Store &snaps_;
  rc522::Mfrc522 chip_;
  SPIClass *spi_ = nullptr;
  QueueHandle_t mailbox_ = nullptr;
  std::atomic<uint32_t> nextId_{1};
  std::mutex mutex_;
  DoorState state_;
  std::vector<DoorEvent> events_;
  std::vector<String> outbox_;
  uint32_t eventSeq_ = 0;
  // Waiting for a card, only touched by the task (the app sees it through state_).
  DoorState::Wait wait_ = DoorState::Wait::None;
  uint32_t waitJob_ = 0, waitUntil_ = 0;
  char enrollName_[24] = "";
  door::Role enrollRole_ = door::Role::Resident;
  uint8_t replaceUid_[10] = {}, replaceLen_ = 0;
  snap::Snapshot copySrc_;
  // Poll state, only touched by the task.
  bool present_ = false, chipLost_ = false;
  int misses_ = 0;
  uint32_t lastHealth_ = 0;
  iso14443a::Uid current_;
};

// R7's web side: a JSON API and a WebSocket on port 80, for the React app in esp-labs/apps/door-app.
// ESPAsyncWebServer answers in its own network task, so the screen and the reader never wait.
//
// Endpoints (JSON). Reading is open on your Wi-Fi; every change needs the admin token
// (header "Authorization: Bearer <token>", serial command `token`). The app's dev server adds it
// from esp-labs/apps/door-app/.env, so the token never reaches the browser.
//   GET    /api                  this list
//   GET    /api/status           both locks, where the reader is, reader chip, Wi-Fi, clock,
//                                lockdown, enrollment
//   GET    /api/cards            the card list, each with what a tap would do right now at
//                                each lock: "now": {"front": "granted", "admin": "admins only"}
//   GET    /api/events?since=N   the access log after event N (the last 50 are kept)
//   POST   /api/enroll           {"name": "Anna", "role": "resident|guest|maintenance|admin"}  -> 202 job
//   POST   /api/replace?uid=HEX  a new card takes over this card's name and rules; the old one
//                                is blocked (lost or broken card)                         -> 202 job
//   POST   /api/cancel           stop waiting for a card (enroll, replace, copy)
//   PUT    /api/card?uid=HEX     any of {"name", "role", "blocked", "validUntil", "fromHour",
//                                "toHour", "usesLeft"}                                   -> 200 card
//   DELETE /api/card?uid=HEX     remove it from the list (the card itself is not touched)
//   POST   /api/label?uid=HEX    write its name and role into blocks 4-5 (card on reader) -> 202 job
//   POST   /api/wipe?uid=HEX     data blocks 4-6, 8-10 back to zeros (card on reader)     -> 202 job
//   POST   /api/inspect          read whatever card is on the reader                     -> 202 job
//   GET    /api/snapshots        saved card data (blocks 4-6, 8-10), up to 8
//   POST   /api/save             {"name": "..."} (optional): save the card on the reader  -> 202 job
//   POST   /api/import           {"name", "blocks": [{"block": 4, "hex": "32 hex"}]}      -> 201
//   POST   /api/restore?id=N     write saved data onto the card on the reader             -> 202 job
//   DELETE /api/snapshot?id=N    forget saved data
//   POST   /api/copy             read the card on the reader, then write it onto the next
//                                different card laid down within 20 s                    -> 202 job
//   POST   /api/open?lock=front  open a lock for 5 s from the app (front or admin)
//   PUT    /api/reader-at        {"lock": "front" | "admin"}: which lock the reader is mounted at
//   PUT    /api/lockdown         {"on": true}: only maintenance and admin cards open
//   WS     /ws                   pushes {"type": "status" | "cards" | "snapshots" | "event" | "job", ...}
// A 202 answers {"job": id}; the result arrives later as a "job" message with that id.
#pragma once

#include <ArduinoJson.h>
#include <AsyncJson.h>
#include <ESPAsyncWebServer.h>

#include <mutex>

#include "api_token.h"
#include "door.h"
#include "registry.h"
#include "snapshots.h"

class DoorApi {
 public:
  DoorApi(Registry &reg, snap::Store &snaps, Door &door, const ApiToken &token)
      : reg_(reg), snaps_(snaps), door_(door), token_(token) {}

  void begin() {
    ws_.onEvent([this](AsyncWebSocket *, AsyncWebSocketClient *client, AwsEventType type, void *, uint8_t *, size_t) {
      if (type != WS_EVT_CONNECT) return;
      std::lock_guard<std::mutex> lock(mutex_);  // the latest picture straight away
      if (!status_.isEmpty()) client->text(wrap("status", status_));
      client->text(wrap("cards", cardsJson()));
      client->text(wrap("snapshots", snapshotsJson()));
    });
    server_.addHandler(&ws_);

    auto get = [this](const char *path, ArRequestHandlerFunction fn) { server_.on(AsyncURIMatcher::exact(path), HTTP_GET, fn); };
    auto post = [this](const char *path, ArRequestHandlerFunction fn) { server_.on(AsyncURIMatcher::exact(path), HTTP_POST, fn); };

    server_.on(AsyncURIMatcher::exact("/"), HTTP_GET, [](AsyncWebServerRequest *req) {
      req->send(200, "text/plain", "rfid-lab-r7, the bench door. Use the React app in esp-labs/apps/door-app, or the JSON API at /api\n");
    });
    get("/api", [](AsyncWebServerRequest *req) { req->send(200, "application/json", kIndex); });
    get("/api/status", [this](AsyncWebServerRequest *req) {
      std::lock_guard<std::mutex> lock(mutex_);
      if (status_.isEmpty()) return error(req, 503, "starting up");
      req->send(200, "application/json", status_);
    });
    get("/api/cards", [this](AsyncWebServerRequest *req) { req->send(200, "application/json", cardsJson()); });
    get("/api/events", [this](AsyncWebServerRequest *req) {
      const uint32_t since = req->hasParam("since") ? uint32_t(req->getParam("since")->value().toInt()) : 0;
      JsonDocument d;
      JsonArray a = d.to<JsonArray>();
      for (const DoorEvent &e : door_.events(since)) {
        JsonObject o = a.add<JsonObject>();
        o["seq"] = e.seq, o["at"] = e.at, o["uid"] = doorjson::copied(e.uid), o["name"] = doorjson::copied(e.name), o["what"] = doorjson::copied(e.what),
        o["decision"] = doorjson::copied(e.decision), o["lock"] = doorjson::copied(e.lock);
      }
      send(req, 200, d);
    });

    json("/api/enroll", HTTP_POST, [this](AsyncWebServerRequest *req, JsonObjectConst body) {
      Door::Request r;
      r.job = Door::Job::Enroll;
      const char *name = body["name"] | "";
      if (!validName(name)) return error(req, 400, "name: 1-23 plain characters (A-Z, digits, space, - . ')");
      strlcpy(r.name, name, sizeof(r.name));
      if (!door::roleFromName(body["role"] | "resident", r.role)) return error(req, 400, "role: resident, guest, maintenance or admin");
      queued(req, door_.submit(r));
    });
    post("/api/cancel", [this](AsyncWebServerRequest *req) { simpleJob(req, Door::Job::Cancel); });
    json("/api/card", HTTP_PUT, [this](AsyncWebServerRequest *req, JsonObjectConst body) { editCard(req, body); });
    server_.on(AsyncURIMatcher::exact("/api/card"), HTTP_DELETE, [this](AsyncWebServerRequest *req) {
      uint8_t uid[10], len = 0;
      if (!admin(req) || !uidParam(req, uid, len)) return;
      if (!reg_.remove(uid, len)) return error(req, 404, "no card with this uid in the list");
      req->send(200, "application/json", "{\"ok\":true}");
    });
    for (const char *path : {"/api/label", "/api/wipe", "/api/replace"}) {
      post(path, [this, path](AsyncWebServerRequest *req) {
        Door::Request r;
        if (!admin(req) || !uidParam(req, r.uid, r.uidLen)) return;
        r.job = strcmp(path, "/api/label") == 0 ? Door::Job::Label : strcmp(path, "/api/wipe") == 0 ? Door::Job::Wipe : Door::Job::Replace;
        queued(req, door_.submit(r));
      });
    }
    post("/api/inspect", [this](AsyncWebServerRequest *req) { simpleJob(req, Door::Job::Inspect); });

    // Saved card data.
    get("/api/snapshots", [this](AsyncWebServerRequest *req) { req->send(200, "application/json", snapshotsJson()); });
    json("/api/save", HTTP_POST, [this](AsyncWebServerRequest *req, JsonObjectConst body) {
      Door::Request r;
      r.job = Door::Job::Save;
      const char *name = body["name"] | "";
      if (name[0] && !validName(name)) return error(req, 400, "name: 1-23 plain characters (A-Z, digits, space, - . ')");
      strlcpy(r.name, name, sizeof(r.name));
      queued(req, door_.submit(r));
    });
    json("/api/import", HTTP_POST, [this](AsyncWebServerRequest *req, JsonObjectConst body) { importSnapshot(req, body); }, 1024);
    post("/api/restore", [this](AsyncWebServerRequest *req) {
      Door::Request r;
      if (!admin(req) || !idParam(req, r.snapshot)) return;
      r.job = Door::Job::Restore;
      queued(req, door_.submit(r));
    });
    server_.on(AsyncURIMatcher::exact("/api/snapshot"), HTTP_DELETE, [this](AsyncWebServerRequest *req) {
      uint32_t id = 0;
      if (!admin(req) || !idParam(req, id)) return;
      if (!snaps_.remove(id)) return error(req, 404, "no saved data with this id");
      req->send(200, "application/json", "{\"ok\":true}");
    });
    post("/api/copy", [this](AsyncWebServerRequest *req) { simpleJob(req, Door::Job::Copy); });

    post("/api/open", [this](AsyncWebServerRequest *req) {
      Door::Request r;
      r.job = Door::Job::Open;
      if (!admin(req) || !lockParam(req, r.lock)) return;
      queued(req, door_.submit(r));
    });
    post("/api/chip-reset", [this](AsyncWebServerRequest *req) { simpleJob(req, Door::Job::ChipReset); });
    json("/api/lockdown", HTTP_PUT, [this](AsyncWebServerRequest *req, JsonObjectConst body) {
      if (!body["on"].is<bool>()) return error(req, 400, "send {\"on\": true} or {\"on\": false}");
      reg_.setLockdown(body["on"].as<bool>());
      req->send(200, "application/json", body["on"].as<bool>() ? "{\"lockdown\":true}" : "{\"lockdown\":false}");
    });
    json("/api/reader-at", HTTP_PUT, [this](AsyncWebServerRequest *req, JsonObjectConst body) {
      door::Lock at;
      if (!door::lockFromId(body["lock"] | "", at)) return error(req, 400, "send {\"lock\": \"front\"} or {\"lock\": \"admin\"}");
      reg_.setReaderAt(at);
      log_i("the reader is now at the %s", door::lockTitle(at));
      req->send(200, "application/json", at == door::Lock::AdminRoom ? "{\"readerAt\":\"admin\"}" : "{\"readerAt\":\"front\"}");
    });

    server_.onNotFound([](AsyncWebServerRequest *req) { error(req, 404, "no such endpoint, see /api"); });
    server_.begin();
    log_i("Web server on port 80: API at /api, live updates at /ws");
  }

  // ---- From loop(): the status, card list changes and the reader's messages, to every client ----

  void publishStatus(const String &json) {
    {
      std::lock_guard<std::mutex> lock(mutex_);
      status_ = json;
    }
    if (ws_.count()) ws_.textAll(wrap("status", json));
  }

  void loop() {
    const uint32_t now = millis();
    if (now - lastCleanup_ > 2000) lastCleanup_ = now, ws_.cleanupClients();
    String msg;
    while (door_.takeMessage(msg))
      if (ws_.count()) ws_.textAll(msg);
    // The list changed (an edit, a tap, an enrollment), or a minute passed ("now" depends on the time).
    const uint32_t v = reg_.version();
    if (v != cardsVersion_ || now - cardsSent_ > 60'000) {
      cardsVersion_ = v, cardsSent_ = now;
      if (ws_.count()) ws_.textAll(wrap("cards", cardsJson()));
    }
    if (snaps_.version() != snapsVersion_) {
      snapsVersion_ = snaps_.version();
      if (ws_.count()) ws_.textAll(wrap("snapshots", snapshotsJson()));
    }
  }

  size_t clients() const { return ws_.count(); }

 private:
  using JsonFn = std::function<void(AsyncWebServerRequest *, JsonObjectConst)>;

  // A JSON-body route; admin only (every route with a body changes something).
  void json(const char *path, WebRequestMethodComposite method, JsonFn fn, size_t maxBytes = 512) {
    auto *h = new AsyncCallbackJsonWebHandler(path, [this, fn](AsyncWebServerRequest *req, JsonVariant &body) {
      if (!admin(req)) return;
      if (!body.is<JsonObject>()) return error(req, 400, "send a JSON object");
      fn(req, body.as<JsonObjectConst>());
    });
    h->setMethod(method);
    h->setMaxContentLength(maxBytes);
    server_.addHandler(h);
  }

  // ?lock=front|admin, front when left out.
  static bool lockParam(AsyncWebServerRequest *req, door::Lock &out) {
    out = door::Lock::Front;
    if (!req->hasParam("lock")) return true;
    if (door::lockFromId(req->getParam("lock")->value().c_str(), out)) return true;
    error(req, 400, "lock: front or admin");
    return false;
  }

  void simpleJob(AsyncWebServerRequest *req, Door::Job job) {
    if (!admin(req)) return;
    Door::Request r;
    r.job = job;
    queued(req, door_.submit(r));
  }

  void editCard(AsyncWebServerRequest *req, JsonObjectConst b) {
    uint8_t uid[10], len = 0;
    if (!uidParam(req, uid, len)) return;
    // Check everything first, then change the card in one go.
    const char *name = b["name"] | static_cast<const char *>(nullptr);
    if (name && !validName(name)) return error(req, 400, "name: 1-23 plain characters (A-Z, digits, space, - . ')");
    door::Role role{};
    const bool hasRole = !b["role"].isNull();
    if (hasRole && !door::roleFromName(b["role"] | "", role)) return error(req, 400, "role: resident, guest, maintenance or admin");
    if (!b["blocked"].isNull() && !b["blocked"].is<bool>()) return error(req, 400, "blocked: true or false");
    const long until = b["validUntil"] | -1L, from = b["fromHour"] | -1L, to = b["toHour"] | -1L, uses = b["usesLeft"] | -2L;
    if (!b["validUntil"].isNull() && until < 0) return error(req, 400, "validUntil: unix seconds, 0 = no end date");
    if ((!b["fromHour"].isNull() && (from < 0 || from > 23)) || (!b["toHour"].isNull() && (to < 0 || to > 24)))
      return error(req, 400, "fromHour 0-23, toHour 0-24 (equal = any time)");
    if (!b["usesLeft"].isNull() && (uses < -1 || uses > 9999)) return error(req, 400, "usesLeft: -1 (unlimited) to 9999");
    door::Card after;
    const bool found = reg_.update(uid, len, [&](door::Card &c) {
      if (name) strlcpy(c.name, name, sizeof(c.name));
      if (hasRole) c.role = role;
      if (b["blocked"].is<bool>()) c.blocked = b["blocked"].as<bool>();
      if (!b["validUntil"].isNull()) c.validUntil = uint32_t(until);
      if (!b["fromHour"].isNull()) c.fromHour = uint8_t(from);
      if (!b["toHour"].isNull()) c.toHour = uint8_t(to == 24 ? 0 : to);
      if (!b["usesLeft"].isNull()) c.usesLeft = int16_t(uses);
    }, &after);
    if (!found) return error(req, 404, "no card with this uid in the list");
    door::Clock clk;
    doorjson::clockNow(clk);
    JsonDocument d;
    d["ok"] = true;
    doorjson::card(d["card"].to<JsonObject>(), after, clk, reg_.lockdown());
    send(req, 200, d);
  }

  // A snapshot from a file the app saved earlier: lab blocks only, each 16 bytes as 32 hex digits.
  void importSnapshot(AsyncWebServerRequest *req, JsonObjectConst b) {
    const char *name = b["name"] | "";
    if (!validName(name)) return error(req, 400, "name: 1-23 plain characters (A-Z, digits, space, - . ')");
    JsonArrayConst blocks = b["blocks"];
    if (blocks.isNull() || blocks.size() == 0 || blocks.size() > snap::kBlocks)
      return error(req, 400, "blocks: 1-6 entries of {\"block\": 4|5|6|8|9|10, \"hex\": 32 hex digits}");
    snap::Snapshot s;
    strlcpy(s.name, name, sizeof(s.name));
    for (JsonObjectConst one : blocks) {
      const int i = snap::slotOf(one["block"] | -1);
      if (i < 0 || (s.have & (1 << i)) || !hexBlock(one["hex"] | "", s.data[i]))
        return error(req, 400, "each block once: {\"block\": 4|5|6|8|9|10, \"hex\": 32 hex digits}");
      s.have |= uint8_t(1 << i);
    }
    door::Clock clk;
    doorjson::clockNow(clk);
    s.at = clk.synced ? clk.now : 0;
    if (!snaps_.add(s)) return error(req, 409, "8 snapshots saved already: delete one first");
    JsonDocument d;
    doorjson::snapshot(d.to<JsonObject>(), s);
    send(req, 201, d);
  }

  static bool hexBlock(const char *hex, uint8_t out[16]) {
    if (strlen(hex) != 32) return false;
    for (int i = 0; i < 32; i++)
      if (!isxdigit(uint8_t(hex[i]))) return false;
    for (int i = 0; i < 16; i++) {
      const char two[3] = {hex[i * 2], hex[i * 2 + 1], 0};
      out[i] = uint8_t(strtoul(two, nullptr, 16));
    }
    return true;
  }

  String snapshotsJson() {
    JsonDocument d;
    JsonArray a = d.to<JsonArray>();
    for (const snap::Snapshot &s : snaps_.list()) doorjson::snapshot(a.add<JsonObject>(), s);
    String out;
    serializeJson(d, out);
    return out;
  }

  String cardsJson() {
    door::Clock clk;
    doorjson::clockNow(clk);
    const bool lockdown = reg_.lockdown();
    JsonDocument d;
    JsonArray a = d.to<JsonArray>();
    for (const door::Card &c : reg_.list()) doorjson::card(a.add<JsonObject>(), c, clk, lockdown);
    String out;
    serializeJson(d, out);
    return out;
  }

  // Names go to a 16-character card block and a small screen font: plain ASCII only.
  static bool validName(const char *s) {
    const size_t n = strlen(s);
    if (n == 0 || n > 23) return false;
    for (size_t i = 0; i < n; i++)
      if (!(isalnum(uint8_t(s[i])) || strchr(" -.'_", s[i]))) return false;
    return true;
  }

  bool admin(AsyncWebServerRequest *req) {
    if (req->hasHeader("Authorization") && token_.allows(req->header("Authorization"))) return true;
    error(req, 401, "admin action: send Authorization: Bearer <token> (serial command: token)");
    return false;
  }

  bool uidParam(AsyncWebServerRequest *req, uint8_t *uid, uint8_t &len) {
    if (req->hasParam("uid") && door::uidFromHex(req->getParam("uid")->value().c_str(), uid, len)) return true;
    error(req, 400, "uid: 8, 14 or 20 hex digits, e.g. ?uid=9C4F2A1B");
    return false;
  }

  bool idParam(AsyncWebServerRequest *req, uint32_t &id) {
    const long v = req->hasParam("id") ? req->getParam("id")->value().toInt() : 0;
    if (v > 0) {
      id = uint32_t(v);
      return true;
    }
    error(req, 400, "id: the snapshot's number, e.g. ?id=3");
    return false;
  }

  static void queued(AsyncWebServerRequest *req, uint32_t id) {
    if (!id) return error(req, 503, "the reader is busy, try again");
    req->send(202, "application/json", String("{\"job\":") + id + "}");
  }

  static void send(AsyncWebServerRequest *req, int code, JsonDocument &d) {
    String out;
    serializeJson(d, out);
    req->send(code, "application/json", out);
  }

  static void error(AsyncWebServerRequest *req, int code, const char *message) {
    JsonDocument d;
    d["error"] = message;
    send(req, code, d);
  }

  static String wrap(const char *type, const String &data) { return String("{\"type\":\"") + type + "\",\"data\":" + data + "}"; }

  static constexpr const char *kIndex =
      "{\"endpoints\":[\"GET /api/status\",\"GET /api/cards\",\"GET /api/events?since=N\",\"POST /api/enroll {name,role}\","
      "\"POST /api/replace?uid=HEX\",\"POST /api/cancel\",\"PUT /api/card?uid=HEX {name,role,blocked,validUntil,fromHour,toHour,usesLeft}\","
      "\"DELETE /api/card?uid=HEX\",\"POST /api/label?uid=HEX\",\"POST /api/wipe?uid=HEX\",\"POST /api/inspect\","
      "\"GET /api/snapshots\",\"POST /api/save {name}\",\"POST /api/import {name,blocks}\",\"POST /api/restore?id=N\","
      "\"DELETE /api/snapshot?id=N\",\"POST /api/copy\","
      "\"POST /api/open?lock=front|admin\",\"PUT /api/reader-at {lock}\",\"POST /api/chip-reset\",\"PUT /api/lockdown {on}\",\"WS /ws\"],"
      "\"admin\":\"every change: Authorization: Bearer <token>\"}";

  Registry &reg_;
  snap::Store &snaps_;
  Door &door_;
  const ApiToken &token_;
  AsyncWebServer server_{80};
  AsyncWebSocket ws_{"/ws"};
  std::mutex mutex_;
  String status_;
  uint32_t lastCleanup_ = 0, cardsVersion_ = 0, cardsSent_ = 0, snapsVersion_ = 0;
};

