constexpr int kW = 320, kH = 170;
constexpr uint16_t kOpen = rgb(60, 210, 120), kDenied = rgb(255, 96, 84), kEnroll = rgb(90, 160, 255),
                   kCopy = rgb(190, 130, 255), kAdmin = rgb(236, 186, 80);

inline void text(FrameBuffer &fb, int x, int y, uint16_t c, const char *s, const GFXfont *f = nullptr) {
  fb.setFont(f);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline int width(FrameBuffer &fb, const char *s, const GFXfont *f) {
  fb.setFont(f);
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void header(FrameBuffer &fb, const char *view, int index, int count, const DoorState &s, bool lockdown) {
  text(fb, 8, 18, pal::ink, "DOOR ", &FreeSansBold9pt7b);
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  if (lockdown) {
    fb.fillRoundRect(150, 6, 76, 16, 4, pal::amber);
    text(fb, 158, 10, pal::night, "LOCKDOWN");
  }
  const int first = 286 - (count - 1) * 10;
  for (int i = 0; i < count; i++) fb.fillCircle(first + i * 10, 14, 3, i == index ? pal::ink : pal::dim);
  fb.fillCircle(304, 14, 5, s.present ? pal::teal : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

inline void footer(FrameBuffer &fb, const char *left, const char *right, uint16_t rightColor) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  text(fb, 6, kH - 9, pal::muted, left);
  fb.setFont(nullptr);
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(right, 0, 0, &x1, &y1, &w, &h);
  text(fb, kW - 6 - w, kH - 9, rightColor, right);
}

// A padlock at (cx, cy): body plus a shackle that lifts and swings open.
inline void padlock(FrameBuffer &fb, int cx, int cy, float open, uint16_t c) {
  const int lift = int(open * 10);
  const int shift = int(open * 14);
  for (int t = 0; t < 4; t++) {
    fb.drawCircleHelper(cx + shift, cy - 18 - lift, 13 - t, 1 | 2, c);  // top half of the shackle
  }
  fb.fillRect(cx + 9 + shift, cy - 18 - lift, 4, 8 + lift, c);  // right leg
  if (open < 0.2f) fb.fillRect(cx - 13, cy - 18, 4, 8, c);       // left leg goes into the body
  fb.fillRoundRect(cx - 20, cy - 10, 40, 32, 5, c);
  fb.fillCircle(cx, cy + 2, 4, pal::night);
  fb.fillRect(cx - 1, cy + 4, 3, 9, pal::night);
}

// The lock the reader is mounted at, big; the other lock on one line underneath.
inline void door(FrameBuffer &fb, const DoorState &ds, door::Lock at, int cards, float t) {
  const DoorState::LockState &s = ds.locks[int(at)];
  const uint32_t now = millis();
  if (ds.wait != DoorState::Wait::None) {
    const bool copy = ds.wait == DoorState::Wait::CopyTarget;
    const uint16_t c = copy ? kCopy : kEnroll;
    const int left = int(max<int32_t>(0, int32_t(ds.waitUntil - now)) / 1000);
    for (int i = 0; i < 3; i++) {
      const float k = fmodf(t * 0.8f + i / 3.0f, 1.0f);
      fb.drawCircle(64, 96, 14 + int(k * 40), mix(c, pal::night, uint8_t(k * 255)));
    }
    if (copy) fb.drawRoundRect(36, 74, 36, 26, 3, pal::muted);  // the source, behind
    fb.fillRoundRect(46, 82, 36, 26, 3, pal::ink);             // the card to lay down
    char line[48];
    if (ds.wait == DoorState::Wait::Enroll) {
      text(fb, 128, 64, c, "ADD A CARD", &FreeSansBold9pt7b);
      snprintf(line, sizeof(line), "Tap the new card for \"%s\"", ds.waitName);
      text(fb, 128, 78, pal::ink, line);
    } else if (ds.wait == DoorState::Wait::Replace) {
      text(fb, 128, 64, c, "REPLACE A CARD", &FreeSansBold9pt7b);
      snprintf(line, sizeof(line), "Tap the new card for \"%s\"", ds.waitName);
      text(fb, 128, 78, pal::ink, line);
      snprintf(line, sizeof(line), "%s will be blocked", ds.waitUid);
      text(fb, 128, 108, pal::muted, line);
    } else {
      text(fb, 128, 64, c, "COPY: 2ND CARD", &FreeSansBold9pt7b);
      text(fb, 128, 78, pal::ink, "Lift the first card, lay");
      text(fb, 128, 90, pal::ink, "the card to copy onto");
      snprintf(line, sizeof(line), "from %s", ds.waitName);
      text(fb, 128, 108, pal::muted, line);
    }
    snprintf(line, sizeof(line), "%d s left", left);
    text(fb, 128, copy ? 120 : 94, pal::muted, line);
    return;
  }
  uint16_t c = pal::muted;
  const char *big = "LOCKED";
  float open = 0;
  if (s.mode == DoorState::Mode::Open) c = kOpen, big = "OPEN", open = 1;
  if (s.mode == DoorState::Mode::Denied) c = kDenied, big = "DENIED";
  if (s.mode == DoorState::Mode::Denied && int((now / 120) % 2)) c = mix(kDenied, pal::night, 90);  // blink
  padlock(fb, 62, 104, open, c);
  text(fb, 122, 42, at == door::Lock::AdminRoom ? kAdmin : pal::muted, at == door::Lock::AdminRoom ? "ADMIN ROOM" : "FRONT DOOR");
  text(fb, 120, 80, c, big, &FreeSansBold18pt7b);
  char line[48];
  if (s.mode == DoorState::Mode::Open) {
    snprintf(line, sizeof(line), "welcome, %s", s.lastName[0] ? s.lastName : "?");
    text(fb, 122, 100, pal::ink, line, &FreeSans9pt7b);
    const int32_t left = max<int32_t>(0, int32_t(s.modeUntil - now));
    fb.drawRect(122, 112, 180, 6, pal::dim);
    fb.fillRect(123, 113, int(178 * left / float(Door::kOpenMs)), 4, kOpen);
  } else if (s.mode == DoorState::Mode::Denied) {
    text(fb, 122, 100, pal::ink, s.lastWhy, &FreeSans9pt7b);
    snprintf(line, sizeof(line), "%s", s.lastName[0] ? s.lastName : s.lastUid);
    text(fb, 122, 112, pal::muted, line);
  } else {
    snprintf(line, sizeof(line), "%d card%s in the list", cards, cards == 1 ? "" : "s");
    text(fb, 122, 100, pal::muted, line);
    if (s.lastWhy[0]) {
      snprintf(line, sizeof(line), "last: %s, %s", s.lastName[0] ? s.lastName : s.lastUid, s.lastWhy);
      text(fb, 122, 114, pal::muted, line);
    }
  }
  const door::Lock other = at == door::Lock::AdminRoom ? door::Lock::Front : door::Lock::AdminRoom;
  const DoorState::LockState &o = ds.locks[int(other)];
  const bool oOpen = o.mode == DoorState::Mode::Open;
  snprintf(line, sizeof(line), "%s: %s", door::lockTitle(other), oOpen ? "open" : "locked");
  text(fb, 122, 134, oOpen ? kOpen : pal::dim, line);
}

inline uint16_t nowColor(door::Decision d) {
  return d == door::Decision::Granted ? kOpen : d == door::Decision::Blocked || d == door::Decision::Unknown ? kDenied : pal::amber;
}

// Each card with what a tap would do at the lock the reader is mounted at.
inline void cards(FrameBuffer &fb, const std::vector<door::Card> &list, const door::Clock &clk, bool lockdown, door::Lock at) {
  if (list.empty()) {
    text(fb, 8, 44, pal::ink, "No cards yet.");
    text(fb, 8, 58, pal::muted, "Add one from the app (Add card),");
    text(fb, 8, 70, pal::muted, "or serial: enroll <name>");
    return;
  }
  const int rows = min<int>(list.size(), 9);
  for (int i = 0; i < rows; i++) {
    const door::Card &c = list[i];
    const door::Decision d = door::decide(&c, clk, lockdown, at);
    const int y = 36 + i * 13;
    fb.fillCircle(12, y + 3, 3, nowColor(d));
    text(fb, 22, y, pal::ink, c.name);
    text(fb, 160, y, pal::muted, door::roleName(c.role));
    text(fb, 240, y, nowColor(d), door::decisionName(d));
  }
  if (int(list.size()) > rows) {
    char more[32];
    snprintf(more, sizeof(more), "+ %d more in the app", int(list.size()) - rows);
    text(fb, 22, 36 + rows * 13, pal::muted, more);
  }
}

inline void history(FrameBuffer &fb, const std::vector<DoorEvent> &events) {
  if (events.empty()) {
    text(fb, 8, 44, pal::muted, "No events yet: tap a card.");
    return;
  }
  const int n = events.size(), from = max(0, n - 9);
  for (int i = from; i < n; i++) {
    const DoorEvent &e = events[i];
    const int y = 36 + (i - from) * 13;
    char when[8] = "--:--";
    if (e.at) {
      const time_t at = e.at;
      struct tm lt;
      localtime_r(&at, &lt);
      strftime(when, sizeof(when), "%H:%M", &lt);
    }
    text(fb, 6, y, pal::muted, when);
    text(fb, 44, y, pal::ink, e.name[0] ? e.name : e.uid[0] ? e.uid : "-");
    const bool tap = strcmp(e.what, "tap") == 0;
    const uint16_t c = tap ? (strcmp(e.decision, "granted") == 0 ? kOpen : kDenied) : kEnroll;
    text(fb, 180, y, c, tap ? e.decision : e.what);
  }
}

}  // namespace dv

// The bench door's card list: up to 20 cards, kept in NVS (namespace "door") so it survives
// power-off and re-flashing. This list, not the card, decides who may open the door.
//
// Two tasks use it: the web server (the app edits cards) and the reader task (a tap is checked
// and counted). Every method takes the mutex, so neither ever sees a half-changed list.
//
// Each change saves the whole list (about 1.2 KB) to flash. Flash wears out after ~100,000 writes
// per spot; NVS spreads the writes around, so a few hundred taps a day are nothing.
#pragma once

#include <Preferences.h>

#include <functional>
#include <mutex>
#include <vector>

#include "access_rules.h"

class Registry {
 public:
  static constexpr int kMax = 20;
  static constexpr uint8_t kFormat = 1;  // bump when door::Card changes: an old list is then ignored

  enum class AddResult { Added, Exists, Full };

  void begin() {
    std::lock_guard<std::mutex> lock(mutex_);
    Preferences p;
    p.begin("door", true);
    const uint8_t format = p.getUChar("format", 0);
    lockdown_ = p.getBool("lockdown", false);
    readerAt_ = p.getUChar("at", 0) == uint8_t(door::Lock::AdminRoom) ? door::Lock::AdminRoom : door::Lock::Front;
    if (format == kFormat) {
      count_ = std::min<int>(p.getUChar("count", 0), kMax);
      if (count_ && p.getBytes("cards", cards_, sizeof(door::Card) * count_) != sizeof(door::Card) * count_) count_ = 0;
    } else if (format != 0) {
      log_w("card list saved by an older firmware (format %u): starting with an empty list", format);
    }
    p.end();
    log_i("card list: %d card%s, lockdown %s, reader at the %s", count_, count_ == 1 ? "" : "s", lockdown_ ? "ON" : "off",
          door::lockTitle(readerAt_));
  }

  int count() {
    std::lock_guard<std::mutex> lock(mutex_);
    return count_;
  }
  uint32_t version() {
    std::lock_guard<std::mutex> lock(mutex_);
    return version_;
  }

  bool lockdown() {
    std::lock_guard<std::mutex> lock(mutex_);
    return lockdown_;
  }
  void setLockdown(bool on) {
    std::lock_guard<std::mutex> lock(mutex_);
    lockdown_ = on;
    Preferences p;
    p.begin("door", false);
    p.putBool("lockdown", on);
    p.end();
    version_++;
  }

  // Which lock the one reader serves. Saved, so it stays put after a restart.
  door::Lock readerAt() {
    std::lock_guard<std::mutex> lock(mutex_);
    return readerAt_;
  }
  void setReaderAt(door::Lock at) {
    std::lock_guard<std::mutex> lock(mutex_);
    readerAt_ = at;
    Preferences p;
    p.begin("door", false);
    p.putUChar("at", uint8_t(at));
    p.end();
    version_++;
  }

  std::vector<door::Card> list() {
    std::lock_guard<std::mutex> lock(mutex_);
    return std::vector<door::Card>(cards_, cards_ + count_);
  }

  bool get(const uint8_t *uid, uint8_t len, door::Card &out) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    if (i < 0) return false;
    out = cards_[i];
    return true;
  }

  AddResult add(const door::Card &c) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (find(c.uid, c.uidLen) >= 0) return AddResult::Exists;
    if (count_ >= kMax) return AddResult::Full;
    cards_[count_++] = c;
    save();
    return AddResult::Added;
  }

  // Change one card in place; false when it isn't in the list.
  bool update(const uint8_t *uid, uint8_t len, const std::function<void(door::Card &)> &change, door::Card *after = nullptr) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    if (i < 0) return false;
    change(cards_[i]);
    if (after) *after = cards_[i];
    save();
    return true;
  }

  bool remove(const uint8_t *uid, uint8_t len) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    if (i < 0) return false;
    for (int k = i; k + 1 < count_; k++) cards_[k] = cards_[k + 1];
    count_--;
    save();
    return true;
  }

  // A tap: decide with the list as it is right now, then count it. `out` is the card after the
  // tap (uses already reduced); `known` says whether it was in the list at all.
  door::Decision tap(const uint8_t *uid, uint8_t len, const door::Clock &clk, door::Lock at, door::Card &out, bool &known) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    known = i >= 0;
    const door::Decision d = door::decide(known ? &cards_[i] : nullptr, clk, lockdown_, at);
    if (!known) return d;
    door::Card &c = cards_[i];
    c.taps++;
    if (clk.synced) c.lastSeen = clk.now;
    if (d == door::Decision::Granted && c.usesLeft > 0) c.usesLeft--;
    out = c;
    save();
    return d;
  }

 private:
  int find(const uint8_t *uid, uint8_t len) const {
    for (int i = 0; i < count_; i++)
      if (cards_[i].uidLen == len && memcmp(cards_[i].uid, uid, len) == 0) return i;
    return -1;
  }

  void save() {
    Preferences p;
    p.begin("door", false);
    p.putUChar("format", kFormat);
    p.putUChar("count", uint8_t(count_));
    if (count_) p.putBytes("cards", cards_, sizeof(door::Card) * count_);
    else if (p.isKey("cards")) p.remove("cards");
    p.end();
    version_++;
  }

  std::mutex mutex_;
  door::Card cards_[kMax];
  int count_ = 0;
  bool lockdown_ = false;
  door::Lock readerAt_ = door::Lock::Front;
  uint32_t version_ = 1;
};

// Saved card data ("snapshots"): what a card's lab blocks held at one moment, kept in NVS
// (namespace "snaps", up to 8) so it can be written back onto the same card later, copied onto
// another card, compared, or downloaded by the app as a JSON file.
//
// The lab blocks are the six that Label, Wipe and Inspect use: 4, 5, 6 (sector 1) and 8, 9, 10
// (sector 2), which is where every lab writes (R4's writes, R5's credits, R7's label). Never
// block 0 (the UID) and never a sector trailer (keys and access bits). So a copy carries the
// data, not the identity: the target keeps its own UID, and the door, which decides by UID, sees
// a different card.
#pragma once

#include <Preferences.h>

#include <mutex>
#include <vector>

namespace snap {

constexpr int kBlocks = 6;
constexpr uint8_t kBlock[kBlocks] = {4, 5, 6, 8, 9, 10};

// Position of `block` in kBlock, -1 when it isn't a lab block.
inline int slotOf(int block) {
  for (int i = 0; i < kBlocks; i++)
    if (kBlock[i] == block) return i;
  return -1;
}

struct Snapshot {
  uint32_t id = 0;  // never reused, so the app can't delete the wrong one after a change
  char name[24] = "";
  uint8_t uid[10] = {};  // the card it was read from; length 0 = imported from a file
  uint8_t uidLen = 0;
  uint32_t at = 0;   // unix seconds, 0 without a clock
  uint8_t have = 0;  // bit i: kBlock[i] was readable and data[i] holds it
  uint8_t data[kBlocks][16] = {};

  int count() const { return __builtin_popcount(have); }
};

class Store {
 public:
  static constexpr int kMax = 8;
  static constexpr uint8_t kFormat = 1;  // bump when Snapshot changes

  void begin() {
    std::lock_guard<std::mutex> lock(mutex_);
    Preferences p;
    p.begin("snaps", true);
    if (p.getUChar("format", 0) == kFormat) {
      count_ = std::min<int>(p.getUChar("count", 0), kMax);
      nextId_ = p.getULong("next", 1);
      if (count_ && p.getBytes("list", list_, sizeof(Snapshot) * count_) != sizeof(Snapshot) * count_) count_ = 0;
    }
    p.end();
    log_i("saved card data: %d snapshot%s", count_, count_ == 1 ? "" : "s");
  }

  uint32_t version() {
    std::lock_guard<std::mutex> lock(mutex_);
    return version_;
  }

  std::vector<Snapshot> list() {
    std::lock_guard<std::mutex> lock(mutex_);
    return std::vector<Snapshot>(list_, list_ + count_);
  }

  bool get(uint32_t id, Snapshot &out) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(id);
    if (i < 0) return false;
    out = list_[i];
    return true;
  }

  // Stores a copy with a new id (written into `s`); false when all 8 places are taken.
  bool add(Snapshot &s) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (count_ >= kMax) return false;
    s.id = nextId_++;
    list_[count_++] = s;
    save();
    return true;
  }

  bool remove(uint32_t id) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(id);
    if (i < 0) return false;
    for (int k = i; k + 1 < count_; k++) list_[k] = list_[k + 1];
    count_--;
    save();
    return true;
  }

 private:
  int find(uint32_t id) const {
    for (int i = 0; i < count_; i++)
      if (list_[i].id == id) return i;
    return -1;
  }

  void save() {
    Preferences p;
    p.begin("snaps", false);
    p.putUChar("format", kFormat);
    p.putUChar("count", uint8_t(count_));
    p.putULong("next", nextId_);
    if (count_) p.putBytes("list", list_, sizeof(Snapshot) * count_);
    else if (p.isKey("list")) p.remove("list");
    p.end();
    version_++;
  }

  std::mutex mutex_;
  Snapshot list_[kMax];
  int count_ = 0;
  uint32_t nextId_ = 1, version_ = 1;
};

}  // namespace snap

// The admin token: a random secret that guards the actions that could change the bench (W2:
// firmware update, forgetting the Wi-Fi network, rebooting; R7: every change to the card list).
//
// It is created on first boot from the chip's hardware random number generator and kept in NVS
// (namespace "api", so every lab on this board shares it). It is printed over serial with the
// `token` command, never sent by the API. The Mac side keeps a copy in a git-ignored .env file
// and adds it to admin requests as "Authorization: Bearer <token>". `token new` makes a fresh one.
#pragma once

#include <Arduino.h>
#include <Preferences.h>
#include <esp_random.h>

class ApiToken {
 public:
  void begin() {
    Preferences prefs;
    prefs.begin("api", true);
    token_ = prefs.getString("token", "");
    prefs.end();
    if (token_.length() != 32) regenerate();
  }

  void regenerate() {
    char hex[33];
    for (int i = 0; i < 16; i++) snprintf(hex + i * 2, 3, "%02x", uint8_t(esp_random()));
    token_ = hex;
    Preferences prefs;
    prefs.begin("api", false);
    prefs.putString("token", token_);
    prefs.end();
  }

  const String &value() const { return token_; }

  // Compares in constant time, so response timing doesn't leak how many characters matched.
  bool allows(const String &authorizationHeader) const {
    const String expected = "Bearer " + token_;
    if (authorizationHeader.length() != expected.length()) return false;
    uint8_t diff = 0;
    for (size_t i = 0; i < expected.length(); i++) diff |= uint8_t(authorizationHeader[i] ^ expected[i]);
    return diff == 0;
  }

 private:
  String token_;
};

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

