// Our own off-screen picture, drawn with the normal Adafruit GFX calls.
//
// Lesson 03 used GFXcanvas16, which always lands in PSRAM (big but slow memory outside the chip).
// Here we choose: fast internal RAM when a big enough block is free, PSRAM otherwise.
// The serial log at start-up tells you which one you got.
#pragma once

#include <Adafruit_GFX.h>
#include <esp_heap_caps.h>

#include <algorithm>

class FrameBuffer : public Adafruit_GFX {
 public:
  FrameBuffer(int16_t w, int16_t h) : Adafruit_GFX(w, h) {}
  ~FrameBuffer() override { heap_caps_free(buf_); }

  bool begin() {
    const size_t bytes = bytesUsed();
    buf_ = static_cast<uint16_t *>(heap_caps_malloc(bytes, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
    internal_ = buf_ != nullptr;
    if (buf_ == nullptr) buf_ = static_cast<uint16_t *>(heap_caps_malloc(bytes, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
    return buf_ != nullptr;
  }

  bool internal() const { return internal_; }
  size_t bytesUsed() const { return size_t(WIDTH) * HEIGHT * sizeof(uint16_t); }
  uint16_t *pixels() { return buf_; }

  // ---- The minimum Adafruit GFX needs (drawPixel) plus fast paths for lines and fills ----

  void drawPixel(int16_t x, int16_t y, uint16_t c) override {
    if (x < 0 || y < 0 || x >= _width || y >= _height) return;
    buf_[y * _width + x] = c;
  }

  void fillScreen(uint16_t c) override { std::fill_n(buf_, size_t(_width) * _height, c); }

  void drawFastHLine(int16_t x, int16_t y, int16_t w, uint16_t c) override {
    if (w < 0) x += w + 1, w = -w;
    if (y < 0 || y >= _height) return;
    if (x < 0) w += x, x = 0;
    if (x + w > _width) w = _width - x;
    if (w > 0) std::fill_n(buf_ + y * _width + x, w, c);
  }

  void drawFastVLine(int16_t x, int16_t y, int16_t h, uint16_t c) override {
    if (h < 0) y += h + 1, h = -h;
    if (x < 0 || x >= _width) return;
    if (y < 0) h += y, y = 0;
    if (y + h > _height) h = _height - y;
    for (uint16_t *p = buf_ + y * _width + x; h-- > 0; p += _width) *p = c;
  }

  void fillRect(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t c) override {
    for (int16_t j = 0; j < h; j++) drawFastHLine(x, y + j, w, c);
  }

 private:
  uint16_t *buf_ = nullptr;
  bool internal_ = false;
};

// R7's access rules: who may open which lock, decided by the board from its own card list.
// Pure C++ (no Arduino), so labs/rfid-lab-r7/test/host/door_rules_test.cpp checks every rule on the Mac.
//
// The card only contributes its UID: everything else (name, role, blocked, dates, hours, uses)
// lives in the board's list, which only the app with the admin token can change.
//
// Two locks: the front door (every role) and the admin room (admin cards only). The one reader
// is mounted at one of them at a time; the app or serial `at front|admin` moves it.
//
// The order of the checks is part of the lesson:
//   1. unknown card              -> Unknown
//   2. blocked                   -> Blocked       (blocking always wins)
//   3. admin room, not an admin  -> AdminsOnly    (the role decides, not the rules below)
//   4. lockdown, not staff       -> Lockdown      (maintenance and admin cards still open)
//   5. needs a clock, none yet   -> NoClock       (fail closed: no time, no time-limited access)
//   6. past its end date         -> Expired
//   7. outside its hours         -> OutsideHours  (hours may wrap past midnight, e.g. 22-6)
//   8. a guest with 0 uses       -> NoUsesLeft
//   9. otherwise                 -> Granted       (a guest's uses go down by one)
#pragma once

#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <initializer_list>

namespace door {

enum class Role : uint8_t { Resident, Guest, Maintenance, Admin };  // stored as a byte: only append
enum class Decision : uint8_t { Granted, Unknown, Blocked, AdminsOnly, Lockdown, NoClock, Expired, OutsideHours, NoUsesLeft };
enum class Lock : uint8_t { Front, AdminRoom };
constexpr int kLocks = 2;

struct Card {
  uint8_t uid[10] = {};
  uint8_t uidLen = 0;
  char name[24] = "";
  Role role = Role::Resident;
  bool blocked = false;
  uint32_t validUntil = 0;           // unix seconds; 0 = no end date
  uint8_t fromHour = 0, toHour = 0;  // allowed local hours [from, to); equal = any time
  int16_t usesLeft = -1;             // -1 = unlimited; guests usually get a number
  uint32_t added = 0, lastSeen = 0;  // unix seconds (0 when the clock wasn't set yet)
  uint32_t taps = 0;
};

struct Clock {
  bool synced = false;  // internet time arrived (NTP)
  uint32_t now = 0;     // unix seconds
  uint8_t hour = 0;     // local hour, 0-23
};

inline bool needsClock(const Card &c) { return c.validUntil != 0 || c.fromHour != c.toHour; }

inline bool inHours(const Card &c, uint8_t hour) {
  if (c.fromHour == c.toHour) return true;
  if (c.fromHour < c.toHour) return hour >= c.fromHour && hour < c.toHour;
  return hour >= c.fromHour || hour < c.toHour;  // wraps past midnight
}

inline Decision decide(const Card *c, const Clock &clk, bool lockdown, Lock lock = Lock::Front) {
  if (!c) return Decision::Unknown;
  if (c->blocked) return Decision::Blocked;
  if (lock == Lock::AdminRoom && c->role != Role::Admin) return Decision::AdminsOnly;
  if (lockdown && c->role != Role::Maintenance && c->role != Role::Admin) return Decision::Lockdown;
  if (needsClock(*c) && !clk.synced) return Decision::NoClock;
  if (c->validUntil && clk.now >= c->validUntil) return Decision::Expired;
  if (!inHours(*c, clk.hour)) return Decision::OutsideHours;
  if (c->usesLeft == 0) return Decision::NoUsesLeft;
  return Decision::Granted;
}

inline const char *decisionName(Decision d) {
  switch (d) {
    case Decision::Granted: return "granted";
    case Decision::Unknown: return "unknown card";
    case Decision::Blocked: return "blocked";
    case Decision::AdminsOnly: return "admins only";
    case Decision::Lockdown: return "lockdown";
    case Decision::NoClock: return "no clock yet";
    case Decision::Expired: return "expired";
    case Decision::OutsideHours: return "outside hours";
    case Decision::NoUsesLeft: return "no uses left";
  }
  return "?";
}

inline const char *roleName(Role r) {
  switch (r) {
    case Role::Resident: return "resident";
    case Role::Guest: return "guest";
    case Role::Maintenance: return "maintenance";
    case Role::Admin: return "admin";
  }
  return "?";
}

inline bool roleFromName(const char *s, Role &out) {
  for (Role r : {Role::Resident, Role::Guest, Role::Maintenance, Role::Admin})
    if (strcmp(s, roleName(r)) == 0) return out = r, true;
  return false;
}

// "front" / "admin" in the API and on serial; "Front door" / "Admin room" for people.
inline const char *lockId(Lock l) { return l == Lock::AdminRoom ? "admin" : "front"; }
inline const char *lockTitle(Lock l) { return l == Lock::AdminRoom ? "Admin room" : "Front door"; }

inline bool lockFromId(const char *s, Lock &out) {
  for (Lock l : {Lock::Front, Lock::AdminRoom})
    if (strcmp(s, lockId(l)) == 0) return out = l, true;
  return false;
}

// UIDs travel as hex text in the API: "9C4F2A1B".
inline void uidToHex(const uint8_t *uid, uint8_t len, char *out, size_t n) {
  size_t p = 0;
  out[0] = 0;
  for (uint8_t i = 0; i < len && p + 2 < n; i++) p += snprintf(out + p, n - p, "%02X", uid[i]);
}

inline bool uidFromHex(const char *hex, uint8_t *out, uint8_t &len) {
  const size_t n = strlen(hex);
  if (n != 8 && n != 14 && n != 20) return false;  // 4, 7 or 10 bytes
  for (size_t i = 0; i < n; i += 2) {
    unsigned v = 0;
    if (sscanf(hex + i, "%2x", &v) != 1) return false;
    out[i / 2] = uint8_t(v);
  }
  len = uint8_t(n / 2);
  return true;
}

}  // namespace door

// ISO/IEC 14443-3 type A: how a reader finds cards and picks one, built on mfrc522.h.
//
//   IDLE --REQA--> READY --anticollision + SELECT--> ACTIVE --(MIFARE auth)--> working
//     ^              (WUPA also wakes HALT)               |
//     +----------------------- HLTA ------------------> HALT (only WUPA wakes it)
//
// Anticollision: every card in the field answers at the same time, bit by bit. Where two cards
// send different bits the reader sees a collision, picks one value (we pick 1), and asks again
// with that prefix: only the cards that match keep answering. A binary-tree walk down the UIDs.
#pragma once

#include "mfrc522.h"

namespace iso14443a {

using rc522::Mfrc522;
using rc522::Status;

constexpr uint8_t REQA = 0x26, WUPA = 0x52, SEL_CL1 = 0x93, SEL_CL2 = 0x95, SEL_CL3 = 0x97, CT = 0x88;

struct Uid {
  uint8_t bytes[10] = {};
  uint8_t size = 0;  // 4, 7 or 10
  uint8_t sak = 0;
  uint8_t atqa[2] = {};

  bool sameAs(const Uid &o) const { return size == o.size && size && memcmp(bytes, o.bytes, size) == 0; }
  // The 4 bytes MIFARE authentication uses: the last 4 of the UID.
  const uint8_t *last4() const { return bytes + (size >= 4 ? size - 4 : 0); }
  // "04:A3:2B:91" style, into out (at least 31 bytes).
  void format(char *out, size_t n, char sep = ':') const {
    size_t p = 0;
    out[0] = 0;
    for (uint8_t i = 0; i < size && p + 4 < n; i++) {
      if (i && sep) out[p++] = sep;
      p += snprintf(out + p, n - p, "%02X", bytes[i]);
    }
  }
};

// One collision the walk resolved: at which cascade level and bit (1-32).
struct Collision {
  uint8_t level, bit;
};
struct Collisions {
  static constexpr int kMax = 8;
  Collision at[kMax];
  int n = 0;
  void add(uint8_t level, uint8_t bit) {
    if (n < kMax) at[n++] = {level, bit};
  }
};

// REQA (idle cards) or WUPA (idle and halted cards): a 7-bit short frame. Answer: 2-byte ATQA.
// Two cards with different ATQAs collide here too; that still means "cards present".
inline Status request(Mfrc522 &chip, uint8_t cmd, uint8_t atqa[2]) {
  chip.clearBits(rc522::CollReg, 0x80);  // ValuesAfterColl = 0: bits after a collision read as 0
  uint8_t len = 2, bits = 7;
  const Status s = chip.transceive(&cmd, 1, atqa, &len, &bits);
  if (s == Status::Collision) return s;
  if (s != Status::Ok) return s;
  if (len != 2 || bits != 0) return Status::ProtocolErr;
  return Status::Ok;
}

// Anticollision + SELECT through every cascade level, until the card says its UID is complete.
// uid.atqa is kept; size, bytes and sak are filled in.
inline Status select(Mfrc522 &chip, Uid &uid, Collisions *collisions = nullptr) {
  chip.clearBits(rc522::CollReg, 0x80);
  uint8_t level = 1;
  for (;;) {
    const uint8_t uidIndex = (level - 1) * 3;
    uint8_t buf[9] = {};  // SEL, NVB, 4 UID bytes (or CT + 3), BCC, CRC_A x2
    buf[0] = level == 1 ? SEL_CL1 : level == 2 ? SEL_CL2 : SEL_CL3;
    int known = 0;  // UID bits of this level we already know
    uint8_t *resp = nullptr;
    uint8_t respLen = 0, bits = 0;
    for (bool selected = false; !selected;) {
      uint8_t sendLen, txLastBits;
      if (known >= 32) {
        // SELECT: all 32 bits known. NVB 0x70 = 7 whole bytes follow the SEL byte's count.
        buf[1] = 0x70;
        buf[6] = rfid::bcc(&buf[2]);
        rfid::appendCrcA(buf, 7);
        txLastBits = 0;
        sendLen = 9;
        resp = &buf[6];  // SAK + CRC_A lands here
        respLen = 3;
      } else {
        // ANTICOLLISION: send what we know; NVB = bytes (high nibble) and extra bits (low nibble).
        txLastBits = known % 8;
        const uint8_t index = 2 + known / 8;
        buf[1] = uint8_t((index << 4) | txLastBits);
        sendLen = index + (txLastBits ? 1 : 0);
        resp = &buf[index];
        respLen = sizeof(buf) - index;
      }
      bits = txLastBits;
      const Status s = chip.transceive(buf, sendLen, resp, &respLen, &bits, txLastBits);
      if (s == Status::Collision) {
        const uint8_t coll = chip.read(rc522::CollReg);
        if (coll & 0x20) return Status::Collision;  // CollPosNotValid
        int pos = coll & 0x1F;
        if (pos == 0) pos = 32;
        if (pos <= known) return Status::ProtocolErr;
        if (collisions) collisions->add(level, uint8_t(pos));
        // Bits before pos arrived intact (and those after read as 0). Choose 1 at pos, ask again.
        known = pos;
        const int bitInByte = (known - 1) % 8;
        const int byteIndex = 1 + known / 8 + (known % 8 ? 1 : 0);
        buf[byteIndex] |= uint8_t(1 << bitInByte);
      } else if (s != Status::Ok) {
        return s;
      } else if (known >= 32) {
        selected = true;
      } else {
        // The whole UID part arrived: check its BCC before selecting.
        if (buf[6] != rfid::bcc(&buf[2])) return Status::BadBcc;
        known = 32;
      }
    }
    // Copy this level's UID bytes. CT (0x88) first means "more bytes at the next level".
    const bool cascade = buf[2] == CT;
    memcpy(&uid.bytes[uidIndex], &buf[cascade ? 3 : 2], cascade ? 3 : 4);
    if (respLen != 3 || bits != 0) return Status::ProtocolErr;
    if (rfid::crcA(resp, 1) != uint16_t(resp[1] | (resp[2] << 8))) return Status::CrcWrong;
    if (resp[0] & 0x04) {  // SAK bit 3: UID not complete
      if (++level > 3) return Status::ProtocolErr;
      continue;
    }
    uid.sak = resp[0];
    uid.size = uint8_t(3 * level + 1);
    return Status::Ok;
  }
}

// HLTA: the selected card goes to HALT. It answers no command except WUPA. No answer = success.
// ISO 14443-3: an answer within 1 ms would mean "not halted", so we only wait 1 ms, not 25.
inline void halt(Mfrc522 &chip) {
  uint8_t cmd[4] = {0x50, 0x00};
  rfid::appendCrcA(cmd, 2);
  const uint32_t keep = chip.timeoutUs();
  chip.setTimeoutUs(1000);
  chip.transceive(cmd, 4, nullptr, nullptr);
  chip.setTimeoutUs(keep);
}

// Wake every card (WUPA) and select one: what the lab does before any card operation.
inline Status wakeAndSelect(Mfrc522 &chip, Uid &uid, Collisions *collisions = nullptr) {
  chip.stopCrypto1();
  Status s = request(chip, WUPA, uid.atqa);
  if (s != Status::Ok && s != Status::Collision) return s;
  return select(chip, uid, collisions);
}

// ---- Naming frames for the sniffer -------------------------------------------------------------

// What a frame from the reader is. `lastBits` 7 means a short frame.
inline const char *nameReaderFrame(const uint8_t *d, uint8_t len, uint8_t lastBits) {
  if (len == 0) return "";
  if (len == 1 && lastBits == 7) return d[0] == REQA ? "REQA" : d[0] == WUPA ? "WUPA" : "short frame";
  switch (d[0]) {
    case SEL_CL1: case SEL_CL2: case SEL_CL3:
      if (len >= 2 && d[1] == 0x70) return d[0] == SEL_CL1 ? "SELECT CL1" : d[0] == SEL_CL2 ? "SELECT CL2" : "SELECT CL3";
      return d[0] == SEL_CL1 ? "ANTICOLL CL1" : d[0] == SEL_CL2 ? "ANTICOLL CL2" : "ANTICOLL CL3";
    case 0x50: return "HLTA";
    case 0x60: return "AUTH key A";
    case 0x61: return "AUTH key B";
    case 0x30: return "READ";
    case 0xA0: return "WRITE";
    case 0xC0: return "DECREMENT";
    case 0xC1: return "INCREMENT";
    case 0xC2: return "RESTORE";
    case 0xB0: return "TRANSFER";
    default: return len == 16 + 2 ? "block data" : len == 4 + 2 ? "value operand" : "";
  }
}

// What a card's answer is, given what the reader sent just before.
inline const char *nameCardFrame(const uint8_t *prev, uint8_t prevLen, uint8_t prevBits, uint8_t len, uint8_t lastBits) {
  if (len == 1 && lastBits == 4) return "ACK/NAK";
  if (prevLen == 1 && prevBits == 7) return "ATQA";
  if (prevLen >= 2 && (prev[0] == SEL_CL1 || prev[0] == SEL_CL2 || prev[0] == SEL_CL3))
    return prev[1] == 0x70 ? "SAK" : "UID + BCC";
  if (prevLen >= 1 && prev[0] == 0x30) return "16 bytes + CRC";
  return "";
}

}  // namespace iso14443a

// The MFRC522 reader chip (the black square on the blue RC522 board), driven register by register.
// No library: every byte that crosses the SPI bus is written in this file.
//
// Layers, each built on the one before:
//   mfrc522.h         this file: SPI framing, registers, FIFO, commands, timer, waiting, transceive
//   iso14443a.h       the card protocol: wake (REQA/WUPA), anticollision, select, halt
//   mifare_classic.h  the card's memory: authenticate, read, write, value blocks
//
// Section numbers refer to the NXP MFRC522 datasheet rev 3.9:
// https://www.nxp.com/docs/en/data-sheet/MFRC522.pdf
//
// Waiting for the card: the chip raises bits in ComIrqReg when a frame was received or its timer
// ran out. We can learn that two ways (WaitMode):
//   Poll  keep reading ComIrqReg over SPI: simple, but the bus is busy the whole time
//   Irq   sleep until the IRQ wire pulls low: no bus traffic, needs the 7th wire
// The edge lab measures the difference.
#pragma once

#include <Arduino.h>
#include <SPI.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>

#include "rfid_format.h"
#include "trace.h"

namespace rc522 {

// Registers used here (section 9.2).
enum Reg : uint8_t {
  CommandReg = 0x01, ComIEnReg = 0x02, DivIEnReg = 0x03, ComIrqReg = 0x04, DivIrqReg = 0x05,
  ErrorReg = 0x06, Status1Reg = 0x07, Status2Reg = 0x08, FIFODataReg = 0x09, FIFOLevelReg = 0x0A,
  ControlReg = 0x0C, BitFramingReg = 0x0D, CollReg = 0x0E,
  ModeReg = 0x11, TxModeReg = 0x12, RxModeReg = 0x13, TxControlReg = 0x14, TxASKReg = 0x15,
  CRCResultRegH = 0x21, CRCResultRegL = 0x22, ModWidthReg = 0x24, RFCfgReg = 0x26,
  TModeReg = 0x2A, TPrescalerReg = 0x2B, TReloadRegH = 0x2C, TReloadRegL = 0x2D,
  AutoTestReg = 0x36, VersionReg = 0x37,
};

// Commands written to CommandReg (section 10.3).
enum Cmd : uint8_t { Idle = 0x00, Mem = 0x01, CalcCRC = 0x03, Transceive = 0x0C, MFAuthent = 0x0E, SoftReset = 0x0F };

// ComIrqReg bits (section 9.3.1.5).
constexpr uint8_t kTxIRq = 0x40, kRxIRq = 0x20, kIdleIRq = 0x10, kErrIRq = 0x02, kTimerIRq = 0x01;

enum class Status : uint8_t {
  Ok,
  NoAnswer,     // the chip's timer ran out: no card answered (or it answered too late)
  Collision,    // two or more cards answered at once and their bits clashed
  CrcWrong,     // the frame arrived but its checksum doesn't match
  ProtocolErr,  // parity, framing or length wrong: a weak or disturbed signal
  Overflow,     // more bytes arrived than fit in the FIFO
  NoRoom,       // more bytes arrived than our buffer holds
  Nak,          // MIFARE said no (4-bit NAK): wrong key, not allowed, wrong block
  BadBcc,       // a UID part's check byte is wrong
  ChipSilent,   // the chip itself never finished: wiring, power or reset problem
};

inline const char *statusName(Status s) {
  switch (s) {
    case Status::Ok: return "ok";
    case Status::NoAnswer: return "no answer";
    case Status::Collision: return "collision";
    case Status::CrcWrong: return "CRC wrong";
    case Status::ProtocolErr: return "protocol error";
    case Status::Overflow: return "FIFO overflow";
    case Status::NoRoom: return "answer too long";
    case Status::Nak: return "NAK";
    case Status::BadBcc: return "BCC wrong";
    case Status::ChipSilent: return "chip silent";
  }
  return "?";
}

struct Pins {
  int8_t ss, sck, mosi, miso, rst, irq;  // irq = -1: not wired
};

// Counters the edge lab reads.
struct Stats {
  uint32_t spiOps = 0;      // chip-select cycles (one register access or one burst)
  uint32_t spiBytes = 0;    // bytes clocked over SPI, both directions at once
  uint32_t polls = 0;       // ComIrqReg reads spent waiting (Poll mode)
  uint32_t irqWakes = 0;    // times the IRQ wire woke us (Irq mode)
  uint32_t irqMissing = 0;  // times it should have and didn't (the chip had finished anyway)
  uint32_t commands = 0;    // Transceive / MFAuthent runs
  uint32_t lastUs = 0;      // duration of the last command, start to finish
};

class Mfrc522 {
 public:
  enum class WaitMode : uint8_t { Poll, Irq };
  static constexpr uint32_t kDefaultHz = 4'000'000;   // well inside the chip's 10 Mbit/s
  static constexpr uint32_t kMaxHz = 10'000'000;      // section 8.1.2
  static constexpr uint32_t kTimerTickUs = 25;        // 13.56 MHz / (2 x 169 + 1) = 40 kHz
  static constexpr uint32_t kDefaultTimeoutUs = 25'000;

  // Bring the chip up: SPI on its own bus, a hard reset through the RST pin, then our settings.
  // Returns the VersionReg value (0x91 / 0x92 for a genuine chip, 0x00 or 0xFF when nothing answers).
  uint8_t begin(SPIClass &spi, const Pins &pins, Trace *trace = nullptr) {
    spi_ = &spi;
    pins_ = pins;
    trace_ = trace;
    pinMode(pins_.ss, OUTPUT);
    digitalWrite(pins_.ss, HIGH);
    spi_->begin(pins_.sck, pins_.miso, pins_.mosi, -1);  // we drive SS ourselves
    if (pins_.irq >= 0) {
      done_ = xSemaphoreCreateBinary();
      pinMode(pins_.irq, INPUT_PULLUP);
      attachInterruptArg(digitalPinToInterrupt(pins_.irq), onIrq, this, FALLING);
    }
    hardReset();
    return read(VersionReg);
  }

  // RST low = hard power-down (NRSTPD). Rising edge = reset; the oscillator then needs a moment.
  void hardReset() {
    pinMode(pins_.rst, OUTPUT);
    digitalWrite(pins_.rst, LOW);
    delayMicroseconds(100);
    digitalWrite(pins_.rst, HIGH);
    delay(50);
    configure();
  }

  void softReset() {
    write(CommandReg, SoftReset);
    delay(50);
    for (int i = 0; i < 3 && (read(CommandReg) & 0x10); i++) delay(50);  // PowerDown bit clears when ready
    configure();
  }

  // ---- Registers over SPI (section 8.1.2) ----------------------------------------------------
  // One address byte, MSB first: bit 7 = 1 read / 0 write, bits 6-1 = register, bit 0 = 0.

  static uint8_t readAddress(uint8_t reg) { return uint8_t(0x80 | (reg << 1)); }
  static uint8_t writeAddress(uint8_t reg) { return uint8_t((reg << 1) & 0x7E); }

  uint8_t read(uint8_t reg) {
    select();
    spi_->transfer(readAddress(reg));
    const uint8_t v = spi_->transfer(0);
    deselect(2);
    return v;
  }

  void write(uint8_t reg, uint8_t value) {
    select();
    spi_->transfer(writeAddress(reg));
    spi_->transfer(value);
    deselect(2);
  }

  // Burst write: one address byte, then every data byte (into the FIFO, n of them).
  void writeMany(uint8_t reg, const uint8_t *data, size_t n) {
    select();
    spi_->transfer(writeAddress(reg));
    for (size_t i = 0; i < n; i++) spi_->transfer(data[i]);
    deselect(1 + n);
  }

  // Burst read (Table 6): send the address again for every byte but the last, which gets 00.
  // rxAlign > 0: the first byte only fills bits rxAlign..7; bits below it keep what out[0] had
  // (the bits we sent ourselves during anticollision).
  void readMany(uint8_t reg, uint8_t *out, size_t n, uint8_t rxAlign = 0) {
    if (n == 0) return;
    const uint8_t a = readAddress(reg);
    select();
    spi_->transfer(a);
    for (size_t i = 0; i < n; i++) {
      const uint8_t v = spi_->transfer(i + 1 < n ? a : 0);
      if (i == 0 && rxAlign) {
        const uint8_t mask = uint8_t(0xFF << rxAlign);
        out[0] = uint8_t((out[0] & ~mask) | (v & mask));
      } else {
        out[i] = v;
      }
    }
    deselect(1 + n);
  }

  void setBits(uint8_t reg, uint8_t mask) { write(reg, read(reg) | mask); }
  void clearBits(uint8_t reg, uint8_t mask) { write(reg, read(reg) & ~mask); }

  // ---- Settings -------------------------------------------------------------------------------

  uint32_t spiHz() const { return hz_; }
  void setSpiHz(uint32_t hz) { hz_ = hz; }

  // Receiver gain, RFCfgReg bits 6-4 (Table 98). 0-7; 2 and 3 repeat 18 and 23 dB.
  static uint8_t gainDb(uint8_t code) {
    static const uint8_t db[8] = {18, 23, 18, 23, 33, 38, 43, 48};
    return db[code & 7];
  }
  uint8_t gain() const { return gain_; }
  void setGain(uint8_t code) {
    gain_ = code & 7;
    write(RFCfgReg, uint8_t(gain_ << 4));
  }

  void antenna(bool on) {
    if (on) setBits(TxControlReg, 0x03);  // Tx1RFEn + Tx2RFEn: both antenna drivers on
    else clearBits(TxControlReg, 0x03);
    antennaOn_ = on;
    if (trace_) trace_->add(on ? TraceFrame::Kind::FieldOn : TraceFrame::Kind::FieldOff, false, nullptr, 0, 0, false);
  }
  bool antennaOn() const { return antennaOn_; }

  // How long the chip waits for the card's answer before giving up (its own timer, TAuto: starts
  // at the end of our frame). 25 ms by default; the edge lab shrinks it to find the card's limit.
  uint32_t timeoutUs() const { return timeoutUs_; }
  void setTimeoutUs(uint32_t us) {
    timeoutUs_ = us;
    uint32_t ticks = us / kTimerTickUs;
    if (ticks < 1) ticks = 1;
    if (ticks > 0xFFFF) ticks = 0xFFFF;
    write(TReloadRegH, uint8_t(ticks >> 8));
    write(TReloadRegL, uint8_t(ticks & 0xFF));
  }

  WaitMode waitMode() const { return mode_; }
  bool hasIrqPin() const { return pins_.irq >= 0; }
  // Irq mode needs the wire; returns false (and stays in Poll) when IRQ isn't configured.
  bool setWaitMode(WaitMode m) {
    if (m == WaitMode::Irq && !hasIrqPin()) return false;
    mode_ = m;
    // IRQ pin: push-pull (DivIEnReg bit 7), active low (ComIEnReg IRqInv, bit 7).
    write(DivIEnReg, m == WaitMode::Irq ? 0x80 : 0x00);
    write(ComIEnReg, 0x80);
    return true;
  }

  bool crypto1On() { return read(Status2Reg) & 0x08; }
  void stopCrypto1() { clearBits(Status2Reg, 0x08); }

  Stats &stats() { return stats_; }
  Trace *trace() { return trace_; }

  // ---- The CRC coprocessor (section 10.3.1.4) -------------------------------------------------

  Status calcCrc(const uint8_t *data, size_t n, uint8_t out[2]) {
    write(CommandReg, Idle);
    write(DivIrqReg, 0x04);     // clear CRCIRq
    write(FIFOLevelReg, 0x80);  // flush the FIFO
    writeMany(FIFODataReg, data, n);
    write(CommandReg, CalcCRC);
    const int64_t deadline = esp_timer_get_time() + 90'000;
    while (!(read(DivIrqReg) & 0x04)) {
      if (esp_timer_get_time() > deadline) return Status::ChipSilent;
    }
    write(CommandReg, Idle);
    out[0] = read(CRCResultRegL);
    out[1] = read(CRCResultRegH);
    return Status::Ok;
  }

  // ---- Talking to the card ----------------------------------------------------------------------
  //
  // transceive(): put `send` in the FIFO, send it, wait, read the answer.
  //   validBits  in: bits used in the last byte we send (7 for REQA, 0 = all 8)
  //             out: bits used in the last byte received
  //   rxAlign    where the first received bit lands in back[0] (anticollision only)
  //   checkCrc   the answer must end in a correct CRC_A (and a 4-bit answer means NAK)
  Status transceive(const uint8_t *send, uint8_t sendLen, uint8_t *back, uint8_t *backLen,
                    uint8_t *validBits = nullptr, uint8_t rxAlign = 0, bool checkCrc = false) {
    return communicate(Transceive, kRxIRq | kIdleIRq, send, sendLen, back, backLen, validBits, rxAlign, checkCrc);
  }

  // MIFARE authentication, done inside the chip (section 10.3.1.9): we hand it command, block,
  // the 6-byte key and the card's UID; it runs the 3-pass handshake and switches Crypto1 on.
  Status authenticate(uint8_t command, uint8_t block, const uint8_t key[6], const uint8_t uid4[4]) {
    uint8_t buf[12] = {command, block};
    memcpy(buf + 2, key, 6);
    memcpy(buf + 8, uid4, 4);
    // communicate() only traces Transceive frames, so the key never lands in the trace.
    Status s = communicate(MFAuthent, kIdleIRq, buf, sizeof(buf), nullptr, nullptr, nullptr, 0, false);
    memset(buf, 0, sizeof(buf));
    if (s == Status::Ok && !crypto1On()) s = Status::Nak;
    if (trace_ && traceOn_) {
      const uint8_t head[2] = {command, block};
      trace_->add(s == Status::Ok ? TraceFrame::Kind::Auth : TraceFrame::Kind::AuthFail, false, head, 2, 0, false);
    }
    return s;
  }

  // Send `send` and cut the field `cutAfterUs` microseconds after its last bit left the antenna.
  // The edge lab's tear test uses it to interrupt a card in the middle of writing its memory.
  void transmitThenCut(const uint8_t *send, uint8_t sendLen, uint32_t cutAfterUs) {
    write(CommandReg, Idle);
    write(ComIrqReg, 0x7F);
    write(FIFOLevelReg, 0x80);
    writeMany(FIFODataReg, send, sendLen);
    write(BitFramingReg, 0x00);
    if (trace_ && traceOn_) trace_->add(TraceFrame::Kind::Frame, false, send, sendLen, 0, crypto1On());
    write(CommandReg, Transceive);
    setBits(BitFramingReg, 0x80);
    const int64_t deadline = esp_timer_get_time() + 20'000;
    while (!(read(ComIrqReg) & kTxIRq) && esp_timer_get_time() < deadline) {
    }
    const int64_t sent = esp_timer_get_time();
    while (esp_timer_get_time() - sent < int64_t(cutAfterUs)) {
    }
    antenna(false);
    write(CommandReg, Idle);
  }

  // True once if a command finished while the IRQ wire stayed quiet (then cleared).
  bool takeIrqMissed() {
    const bool m = irqMissed_;
    irqMissed_ = false;
    return m;
  }

  // A dip in its 3.3 V resets the chip to its defaults without a word: VersionReg still answers,
  // but the timer prescaler is back to 00h and the antenna drivers are off, so no card is ever
  // found. True when that happened; restoreSettings() puts our configuration back.
  bool settingsLost() {
    return read(TPrescalerReg) != 0xA9 || (read(TxControlReg) & 0x03) != (antennaOn_ ? 0x03 : 0x00);
  }
  void restoreSettings() { configure(); }

  bool traceOn() const { return traceOn_; }
  void setTraceOn(bool on) { traceOn_ = on; }

 private:
  void configure() {
    write(TxModeReg, 0x00);      // 106 kBd, no CRC added by hardware (we add it ourselves)
    write(RxModeReg, 0x00);
    write(ModWidthReg, 0x26);    // modulation pulse width (reset value)
    write(TModeReg, 0x80);       // TAuto: the timer starts when a frame has been sent
    write(TPrescalerReg, 0xA9);  // 13.56 MHz / (2 x 169 + 1) = 40 kHz: one tick = 25 us
    setTimeoutUs(timeoutUs_);
    write(TxASKReg, 0x40);       // Force100ASK: the 100 % ASK pauses ISO 14443-A wants
    write(ModeReg, 0x3D);        // CRC preset 6363h, like CRC_A
    setGain(gain_);
    setWaitMode(mode_);
    antenna(true);
  }

  Status communicate(uint8_t command, uint8_t waitIrq, const uint8_t *send, uint8_t sendLen, uint8_t *back,
                     uint8_t *backLen, uint8_t *validBits, uint8_t rxAlign, bool checkCrc) {
    const uint8_t txLastBits = validBits ? *validBits : 0;
    const bool crypto = command == Transceive && crypto1On();
    stats_.commands++;

    write(CommandReg, Idle);           // stop anything still running
    write(ComIrqReg, 0x7F);            // clear every interrupt bit
    write(FIFOLevelReg, 0x80);         // flush the FIFO
    writeMany(FIFODataReg, send, sendLen);
    write(BitFramingReg, uint8_t((rxAlign << 4) | txLastBits));
    if (mode_ == WaitMode::Irq) {
      write(ComIEnReg, uint8_t(0x80 | waitIrq | kTimerIRq));  // let these reach the IRQ pin
      xSemaphoreTake(done_, 0);                                // forget an old wake-up
    }
    if (trace_ && traceOn_ && command == Transceive)
      trace_->add(TraceFrame::Kind::Frame, false, send, sendLen, txLastBits, crypto);

    const int64_t t0 = esp_timer_get_time();
    write(CommandReg, command);
    if (command == Transceive) setBits(BitFramingReg, 0x80);  // StartSend

    uint8_t irq = 0;
    Status s = wait(waitIrq, irq);
    stats_.lastUs = uint32_t(esp_timer_get_time() - t0);
    if (mode_ == WaitMode::Irq) write(ComIEnReg, 0x80);
    if (s != Status::Ok) {
      write(CommandReg, Idle);
      if (s == Status::NoAnswer && trace_ && traceOn_ && command == Transceive)
        trace_->add(TraceFrame::Kind::NoAnswer, true, nullptr, 0, 0, crypto);
      return s;
    }

    const uint8_t err = read(ErrorReg);
    if (err & 0x10) return Status::Overflow;
    if (err & 0x03) return Status::ProtocolErr;  // ParityErr or ProtocolErr

    uint8_t gotBits = 0;
    if (back && backLen) {
      const uint8_t n = read(FIFOLevelReg) & 0x7F;
      if (n > *backLen) return Status::NoRoom;
      *backLen = n;
      readMany(FIFODataReg, back, n, rxAlign);
      gotBits = read(ControlReg) & 0x07;  // RxLastBits
      if (validBits) *validBits = gotBits;
      if (trace_ && traceOn_ && command == Transceive)
        trace_->add(TraceFrame::Kind::Frame, true, back, n, gotBits, crypto);
    }
    if (err & 0x08) return Status::Collision;

    if (back && backLen && checkCrc) {
      if (*backLen == 1 && gotBits == 4) return Status::Nak;  // MIFARE 4-bit NAK
      if (*backLen < 2 || gotBits != 0) return Status::CrcWrong;
      if (rfid::crcA(back, *backLen - 2) != uint16_t(back[*backLen - 2] | (back[*backLen - 1] << 8))) return Status::CrcWrong;
    }
    return Status::Ok;
  }

  // Wait until one of `waitIrq` is set, the chip's timer runs out, or the chip itself goes quiet.
  Status wait(uint8_t waitIrq, uint8_t &irq) {
    // The chip's timer covers the card; this software deadline covers the chip (a loose wire).
    const int64_t start = esp_timer_get_time();
    const int64_t deadline = start + timeoutUs_ + 40'000;
    if (mode_ == WaitMode::Irq) {
      for (;;) {
        const int64_t left = deadline - esp_timer_get_time();
        const bool woke = left > 0 && xSemaphoreTake(done_, pdMS_TO_TICKS(left / 1000 + 1)) == pdTRUE;
        irq = read(ComIrqReg);
        if (woke) stats_.irqWakes++;
        // Finished without a wake-up: the IRQ wire is missing. The answer is still good; the
        // caller sees irqMissed() and can fall back to Poll.
        if (!woke && (irq & (waitIrq | kTimerIRq))) stats_.irqMissing++, irqMissed_ = true;
        if (irq & waitIrq) return Status::Ok;
        if (irq & kTimerIRq) return Status::NoAnswer;
        if (!woke) return Status::ChipSilent;
        // Woken by an old edge: wait again.
      }
    }
    // Poll: spin for the first 2 ms (most answers come within 1 ms), then check once per tick so
    // the rest of the system can run while we wait out a long timeout.
    for (;;) {
      irq = read(ComIrqReg);
      stats_.polls++;
      if (irq & waitIrq) return Status::Ok;
      if (irq & kTimerIRq) return Status::NoAnswer;
      const int64_t now = esp_timer_get_time();
      if (now > deadline) return Status::ChipSilent;
      if (now - start > 2'000) vTaskDelay(1);
    }
  }

  void select() {
    spi_->beginTransaction(SPISettings(hz_, MSBFIRST, SPI_MODE0));  // section 8.1.2: mode 0
    digitalWrite(pins_.ss, LOW);
  }
  void deselect(size_t bytes) {
    digitalWrite(pins_.ss, HIGH);
    spi_->endTransaction();
    stats_.spiOps++;
    stats_.spiBytes += bytes;
  }

  static void IRAM_ATTR onIrq(void *self) {
    BaseType_t woken = pdFALSE;
    xSemaphoreGiveFromISR(static_cast<Mfrc522 *>(self)->done_, &woken);
    if (woken) portYIELD_FROM_ISR();
  }

  SPIClass *spi_ = nullptr;
  Pins pins_{};
  Trace *trace_ = nullptr;
  SemaphoreHandle_t done_ = nullptr;
  uint32_t hz_ = kDefaultHz;
  uint32_t timeoutUs_ = kDefaultTimeoutUs;
  uint8_t gain_ = 4;  // 33 dB, the reset value
  WaitMode mode_ = WaitMode::Poll;
  bool antennaOn_ = false;
  bool traceOn_ = true;
  bool irqMissed_ = false;
  Stats stats_;
};

// What VersionReg says (section 9.3.4.8), plus the clones sold on cheap RC522 boards.
inline const char *versionName(uint8_t v) {
  switch (v) {
    case 0x91: return "MFRC522 v1.0";
    case 0x92: return "MFRC522 v2.0";
    case 0x88: return "FM17522 (clone)";
    case 0x89: return "FM17522E (clone)";
    case 0xB2: return "FM17522 (clone)";
    case 0x12: return "counterfeit MFRC522";
    case 0x00: return "nothing (MISO stuck low?)";
    case 0xFF: return "nothing (MISO floating?)";
    default: return "unknown chip";
  }
}

}  // namespace rc522

// MIFARE Classic memory on top of iso14443a.h: authenticate a sector, read and write 16-byte
// blocks, and use the card's own value-block arithmetic (increment, decrement, restore, transfer).
//
// Guard rails, because a wrong write can lock a sector forever:
//   - block 0 (manufacturer data) and every sector trailer (keys + access bits) are never written
//   - only data blocks whose access bits allow key A writes are written
#pragma once

#include "iso14443a.h"

namespace mifare {

using iso14443a::Uid;
using rc522::Mfrc522;
using rc522::Status;

constexpr uint8_t AUTH_A = 0x60, AUTH_B = 0x61, READ = 0x30, WRITE = 0xA0;
constexpr uint8_t DECREMENT = 0xC0, INCREMENT = 0xC1, RESTORE = 0xC2, TRANSFER = 0xB0;

// The key every new card ships with (key A of every sector). The labs only use cards you own
// that still have it.
constexpr uint8_t kFactoryKey[6] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};

// Authenticate the sector that holds `block` with key A.
inline Status authA(Mfrc522 &chip, const Uid &uid, uint8_t block, const uint8_t key[6]) {
  return chip.authenticate(AUTH_A, block, key, uid.last4());
}

// A failed authentication drops the card back to IDLE; wake and select it again before retrying.
inline Status reselect(Mfrc522 &chip, Uid &uid) {
  Uid again = uid;
  const Status s = iso14443a::wakeAndSelect(chip, again);
  if (s == Status::Ok && !again.sameAs(uid)) return Status::Collision;  // a different card answered
  return s;
}

inline Status readBlock(Mfrc522 &chip, uint8_t block, uint8_t out[16]) {
  uint8_t cmd[4] = {READ, block};
  rfid::appendCrcA(cmd, 2);
  uint8_t buf[18], len = sizeof(buf);
  const Status s = chip.transceive(cmd, 4, buf, &len, nullptr, 0, true);
  if (s != Status::Ok) return s;
  if (len != 18) return Status::ProtocolErr;
  memcpy(out, buf, 16);
  return Status::Ok;
}

// MIFARE answers each step with a 4-bit ACK (0xA) or NAK (anything else).
inline Status expectAck(Mfrc522 &chip, const uint8_t *frame, uint8_t len) {
  uint8_t ack[1] = {}, n = 1, bits = 0;
  const Status s = chip.transceive(frame, len, ack, &n, &bits);
  if (s != Status::Ok) return s;
  if (n != 1 || bits != 4) return Status::ProtocolErr;
  return (ack[0] & 0x0F) == 0x0A ? Status::Ok : Status::Nak;
}

// Two steps: "WRITE block" -> ACK, then 16 bytes -> ACK. The card commits all 16 bytes or none.
inline Status writeBlockUnchecked(Mfrc522 &chip, uint8_t block, const uint8_t data[16]) {
  uint8_t cmd[4] = {WRITE, block};
  rfid::appendCrcA(cmd, 2);
  Status s = expectAck(chip, cmd, 4);
  if (s != Status::Ok) return s;
  uint8_t frame[18];
  memcpy(frame, data, 16);
  rfid::appendCrcA(frame, 16);
  // The card writes its EEPROM before it ACKs; the 25 ms timer leaves plenty of room.
  return expectAck(chip, frame, 18);
}

// Refuses block 0 and trailers: those writes are how sectors get locked for good.
inline bool writable(int block) { return block > 0 && block < 256 && !rfid::isTrailer(block); }

inline Status writeBlock(Mfrc522 &chip, uint8_t block, const uint8_t data[16]) {
  if (!writable(block)) return Status::Nak;
  return writeBlockUnchecked(chip, block, data);
}

// Value operations: "OP block" -> ACK, then the 4-byte operand. The card doesn't answer the
// operand: silence means it worked (a "passive ACK"). The result sits in the card's internal
// register until TRANSFER writes it to a block.
inline Status valueOp(Mfrc522 &chip, uint8_t op, uint8_t block, int32_t operand) {
  uint8_t cmd[4] = {op, block};
  rfid::appendCrcA(cmd, 2);
  Status s = expectAck(chip, cmd, 4);
  if (s != Status::Ok) return s;
  uint8_t frame[6];
  for (int i = 0; i < 4; i++) frame[i] = uint8_t(uint32_t(operand) >> (8 * i));
  rfid::appendCrcA(frame, 4);
  const uint32_t keep = chip.timeoutUs();
  chip.setTimeoutUs(5000);
  uint8_t ack[1], n = 1, bits = 0;
  s = chip.transceive(frame, 6, ack, &n, &bits);
  chip.setTimeoutUs(keep);
  if (s == Status::NoAnswer) return Status::Ok;  // passive ACK
  if (s == Status::Ok && n == 1 && bits == 4) return Status::Nak;
  return s;
}

inline Status transfer(Mfrc522 &chip, uint8_t block) {
  if (!writable(block)) return Status::Nak;
  uint8_t cmd[4] = {TRANSFER, block};
  rfid::appendCrcA(cmd, 2);
  return expectAck(chip, cmd, 4);
}

}  // namespace mifare

// Pure byte formats of the RFID labs: no hardware, no Arduino, so test/rfid_host_test.cpp can check
// them on the Mac. Everything that talks to the chip lives in the other files.
//
//   crcA()          ISO/IEC 14443-3 CRC_A, the 2-byte checksum after most card frames
//   bcc()           the 1-byte check after each UID part during anticollision
//   AccessBits      a MIFARE Classic sector trailer's bytes 6-8: who may read/write each block
//   ValueBlock      MIFARE Classic's built-in "wallet" format: value, ~value, value, address x4
#pragma once

#include <stdint.h>
#include <string.h>

namespace rfid {

// CRC_A (ISO/IEC 14443-3, annex B): start at 0x6363, process each byte LSB first. The result is
// sent low byte first. The MFRC522 has the same calculation in hardware (CalcCRC command); the
// edge lab compares the two.
inline uint16_t crcA(const uint8_t *data, size_t n) {
  uint16_t crc = 0x6363;
  for (size_t i = 0; i < n; i++) {
    uint8_t ch = data[i] ^ uint8_t(crc & 0xFF);
    ch ^= uint8_t(ch << 4);
    crc = uint16_t((crc >> 8) ^ (uint16_t(ch) << 8) ^ (uint16_t(ch) << 3) ^ (ch >> 4));
  }
  return crc;
}

inline void appendCrcA(uint8_t *frame, size_t n) {
  const uint16_t c = crcA(frame, n);
  frame[n] = uint8_t(c & 0xFF);
  frame[n + 1] = uint8_t(c >> 8);
}

// Block Check Character: XOR of the 4 UID bytes of one cascade level.
inline uint8_t bcc(const uint8_t *four) { return four[0] ^ four[1] ^ four[2] ^ four[3]; }

// ---- MIFARE Classic memory geometry ----------------------------------------------------------
// 1K: 16 sectors x 4 blocks x 16 bytes. Block 0 = manufacturer data (UID, read-only). The last
// block of every sector is its trailer: key A (6) · access bits (3) · user byte (1) · key B (6).

constexpr int kBlockSize = 16;
inline bool isTrailer(int block) { return block < 128 ? (block % 4) == 3 : (block % 16) == 15; }
inline int sectorOf(int block) { return block < 128 ? block / 4 : 32 + (block - 128) / 16; }
inline int firstBlock(int sector) { return sector < 32 ? sector * 4 : 128 + (sector - 32) * 16; }
inline int blocksIn(int sector) { return sector < 32 ? 4 : 16; }
inline int trailerOf(int sector) { return firstBlock(sector) + blocksIn(sector) - 1; }

// ---- Access bits (MIFARE Classic EV1 datasheet MF1S50yyX, section 8.7) ------------------------
// Each block b (0-2 data, 3 = trailer) has three bits C1 C2 C3. They are stored twice, once
// inverted, so a half-written trailer is detectable:
//   byte 6 = ~C2 (high nibble) | ~C1 (low nibble)
//   byte 7 =  C1 (high nibble) | ~C3 (low nibble)
//   byte 8 =  C3 (high nibble) |  C2 (low nibble)
// Bit b of each nibble belongs to block b. The default trailer FF 07 80 gives data blocks 000
// ("anything with key A or B") and the trailer 001 ("key A can do everything").
struct AccessBits {
  uint8_t c1 = 0, c2 = 0, c3 = 0;  // low 4 bits used, bit b = block b

  // false when the inverted copies don't match: never write such a trailer, the sector would lock.
  static bool decode(const uint8_t trailer[16], AccessBits &out) {
    const uint8_t b6 = trailer[6], b7 = trailer[7], b8 = trailer[8];
    out.c1 = b7 >> 4;
    out.c2 = b8 & 0x0F;
    out.c3 = b8 >> 4;
    return (b6 & 0x0F) == (~out.c1 & 0x0F) && (b6 >> 4) == (~out.c2 & 0x0F) && (b7 & 0x0F) == (~out.c3 & 0x0F);
  }

  void encode(uint8_t out3[3]) const {
    out3[0] = uint8_t(((~c2 & 0x0F) << 4) | (~c1 & 0x0F));
    out3[1] = uint8_t(((c1 & 0x0F) << 4) | (~c3 & 0x0F));
    out3[2] = uint8_t(((c3 & 0x0F) << 4) | (c2 & 0x0F));
  }

  // The 3-bit condition of block b (0-3), as the number C1C2C3 (0-7).
  uint8_t condition(int b) const {
    return uint8_t((((c1 >> b) & 1) << 2) | (((c2 >> b) & 1) << 1) | ((c3 >> b) & 1));
  }

  // What a data block's condition allows: read / write / increment / decrement+transfer+restore.
  static const char *dataRule(uint8_t c) {
    static const char *const rules[8] = {
        "read AB write AB inc AB dec AB",  // 000  transport configuration
        "read AB dec AB (value, no top-up)",  // 001
        "read AB, read-only",                // 010
        "read B write B",                    // 011
        "read AB write B",                   // 100
        "read B, read-only",                 // 101
        "read AB write B inc B dec AB",      // 110  value block, top-up with key B
        "locked: nothing",                   // 111
    };
    return rules[c & 7];
  }

  static const char *trailerRule(uint8_t c) {
    static const char *const rules[8] = {
        "A writes keys, bits fixed; B readable",   // 000
        "A writes all (transport)",                // 001
        "read-only; B readable",                   // 010
        "B writes keys + bits",                    // 011
        "B writes keys",                           // 100
        "B writes access bits",                    // 101
        "read-only",                               // 110
        "read-only",                               // 111
    };
    return rules[c & 7];
  }

  // Data blocks that may be written with key A (our lab never uses key B).
  bool keyAWrites(int b) const { return condition(b) == 0; }
  // With these trailer conditions key B is readable, so it can't be used as a key at all.
  bool keyBReadable() const {
    const uint8_t t = condition(3);
    return t == 0 || t == 1 || t == 2;
  }
};

// ---- Value blocks ------------------------------------------------------------------------------
// A signed 32-bit value stored three times (once inverted) plus a 1-byte address four times.
// The card checks this format itself before increment / decrement / restore.
struct ValueBlock {
  static void encode(int32_t value, uint8_t addr, uint8_t out[16]) {
    const uint32_t v = uint32_t(value), nv = ~v;
    for (int i = 0; i < 4; i++) {
      out[i] = uint8_t(v >> (8 * i));
      out[4 + i] = uint8_t(nv >> (8 * i));
      out[8 + i] = uint8_t(v >> (8 * i));
    }
    out[12] = addr, out[13] = uint8_t(~addr), out[14] = addr, out[15] = uint8_t(~addr);
  }

  // false when the block is not a valid value block.
  static bool decode(const uint8_t b[16], int32_t &value, uint8_t &addr) {
    uint32_t v = 0, nv = 0, v2 = 0;
    for (int i = 0; i < 4; i++) {
      v |= uint32_t(b[i]) << (8 * i);
      nv |= uint32_t(b[4 + i]) << (8 * i);
      v2 |= uint32_t(b[8 + i]) << (8 * i);
    }
    if (v != v2 || v != ~nv) return false;
    if (b[12] != b[14] || b[13] != b[15] || uint8_t(~b[12]) != b[13]) return false;
    value = int32_t(v);
    addr = b[12];
    return true;
  }
};

// ---- Card identification -----------------------------------------------------------------------

// From SAK, the select acknowledge (NXP AN10833).
inline const char *cardType(uint8_t sak) {
  switch (sak & 0x7F) {
    case 0x09: return "MIFARE Mini";
    case 0x08: return "MIFARE Classic 1K";
    case 0x18: return "MIFARE Classic 4K";
    case 0x00: return "Ultralight / NTAG";
    case 0x10: case 0x11: return "MIFARE Plus";
    case 0x01: return "TNP3xxx";
    case 0x20: return "ISO 14443-4 (DESFire, phone, bank card)";
    case 0x40: return "NFC peer (ISO 18092)";
    default: return (sak & 0x20) ? "ISO 14443-4" : "unknown";
  }
}

// Sectors our lab can read on this card type, 0 = not a MIFARE Classic.
inline int classicSectors(uint8_t sak) {
  switch (sak & 0x7F) {
    case 0x09: return 5;
    case 0x08: case 0x88: return 16;
    case 0x18: return 40;
    default: return 0;
  }
}

// ATQA arrives low byte first. Bits 7-6 of the low byte: UID size; bits 4-0: anticollision.
inline int atqaUidBytes(const uint8_t atqa[2]) {
  switch ((atqa[0] >> 6) & 3) {
    case 0: return 4;
    case 1: return 7;
    case 2: return 10;
    default: return 0;  // reserved
  }
}

}  // namespace rfid

// A sniffer for the RFID labs: every frame the reader sends to the card and every answer, with a
// timestamp, kept in a small ring. mfrc522.h adds the entries; the screen's trace view and the
// serial printer (`trace on`) read them. Safe to use from two tasks.
#pragma once

#include <Arduino.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>

struct TraceFrame {
  enum class Kind : uint8_t {
    Frame,     // bytes on the air (or their plain text, when Crypto1 is on)
    NoAnswer,  // the card stayed silent until the chip's timer ran out
    Auth,      // the chip ran MIFARE's 3-pass authentication by itself (the key is never stored)
    AuthFail,
    FieldOff,  // antenna switched off (the card loses power)
    FieldOn,
  };
  uint32_t us = 0;  // esp_timer microseconds since boot (low 32 bits: wraps every 71 minutes)
  Kind kind = Kind::Frame;
  bool fromCard = false;  // false: reader -> card (PCD -> PICC)
  bool crypto = false;    // Crypto1 was on: on the air these bytes were encrypted
  uint8_t len = 0;        // whole or partial bytes stored, up to 18
  uint8_t lastBits = 0;   // bits used in the last byte, 0 = all 8
  uint8_t data[18] = {};
};

class Trace {
 public:
  static constexpr int kSize = 64;

  void add(TraceFrame::Kind kind, bool fromCard, const uint8_t *d, uint8_t n, uint8_t lastBits, bool crypto) {
    TraceFrame f;
    f.us = uint32_t(esp_timer_get_time());
    f.kind = kind;
    f.fromCard = fromCard;
    f.crypto = crypto;
    f.len = n > sizeof(f.data) ? sizeof(f.data) : n;
    f.lastBits = lastBits;
    if (d && f.len) memcpy(f.data, d, f.len);
    portENTER_CRITICAL(&mux_);
    frames_[head_ % kSize] = f;
    head_++;
    portEXIT_CRITICAL(&mux_);
  }

  // Sequence number of the next frame to be added: everything before it can be fetched with get().
  uint32_t head() const {
    portENTER_CRITICAL(&mux_);
    const uint32_t h = head_;
    portEXIT_CRITICAL(&mux_);
    return h;
  }

  // Frame number seq, if it is still in the ring.
  bool get(uint32_t seq, TraceFrame &out) const {
    portENTER_CRITICAL(&mux_);
    const bool ok = seq < head_ && head_ - seq <= kSize;
    if (ok) out = frames_[seq % kSize];
    portEXIT_CRITICAL(&mux_);
    return ok;
  }

  // Forget everything added since `seq` (e.g. an empty poll: WUPA, no answer, nothing to show).
  void rollback(uint32_t seq) {
    portENTER_CRITICAL(&mux_);
    if (seq < head_) head_ = seq;
    portEXIT_CRITICAL(&mux_);
  }

  void clear() {
    portENTER_CRITICAL(&mux_);
    head_ = 0;
    portEXIT_CRITICAL(&mux_);
  }

 private:
  mutable portMUX_TYPE mux_ = portMUX_INITIALIZER_UNLOCKED;
  TraceFrame frames_[kSize];
  uint32_t head_ = 0;
};
